const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>美股交易链条观察 · 极简金融排印版</title>\n  <style>\n    :root {\n      --bg: #F6F4EF;\n      --card: #FFFFFF;\n      --sub: #FAF8F4;\n      --warm: #FAF6EC;\n      --warm-bd: #EDE3CC;\n      --blue-bg: #EEF3F8;\n      --blue-bd: #DCE6F0;\n      --ink: #1E2320;\n      --muted: #666F69;\n      --faint: #87908A;\n      --border: #E6E1D6;\n      --sage: #2E6F5E;\n      --sage-bg: #EAF3F0;\n      --terra: #B84A39;\n      --terra-bg: #FBECE9;\n      --ochre: #B87D2B;\n      --ochre-bg: #FDF5E6;\n      --slate: #47627A;\n      --slate-bg: #EDF2F6;\n      --up: #C43E32;\n      --up-bg: #FDECEB;\n      --down: #2E6F5E;\n      --down-bg: #EAF3F0;\n      --sans: \"PingFang SC\", -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"Hiragino Sans GB\", \"Noto Sans SC\", \"Microsoft YaHei\", sans-serif;\n      --mono: \"SF Mono\", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n    }\n\n    body.green-up {\n      --up: #2E6F5E;\n      --up-bg: #EAF3F0;\n      --down: #C43E32;\n      --down-bg: #FDECEB;\n    }\n\n    * { box-sizing: border-box; }\n    html { font-size: 16px; }\n    body {\n      margin: 0;\n      background: var(--bg);\n      color: var(--ink);\n      font-family: var(--sans);\n      font-size: 13px;\n      line-height: 1.62;\n      letter-spacing: 0.012em;\n      font-variant-numeric: tabular-nums;\n      -webkit-font-smoothing: antialiased;\n    }\n\n    .mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }\n    .muted { color: var(--muted); }\n    .faint { color: var(--faint); }\n    .wrap { max-width: 1020px; margin: 0 auto; padding: 18px 16px 52px; }\n\n    /* Header & Pill Nav */\n    .hdr { margin-bottom: 14px; }\n    .hdr-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }\n    .hdr-left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-width: 0; }\n    .hdr h1 { margin: 0; font-size: 22px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.25; color: var(--ink); }\n    .subtitle { margin: 6px 0 0; font-size: 12px; color: var(--muted); }\n    .btn-row { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }\n\n    .sync-pill {\n      display: inline-flex; align-items: center; gap: 6px;\n      padding: 4px 11px; border-radius: 999px;\n      background: var(--sage-bg); color: var(--sage);\n      font-size: 11.5px; font-weight: 600; max-width: 100%;\n    }\n    .sync-pill.cached { background: var(--slate-bg); color: var(--slate); }\n    .sync-pill.err { background: var(--terra-bg); color: var(--terra); }\n    .sync-dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; flex-shrink: 0; }\n    .sync-dot.busy { animation: pulse 1.2s ease-in-out infinite; }\n    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .3; } }\n\n    .btn {\n      appearance: none; border: 1px solid rgba(30,35,32,.1); background: var(--card); color: var(--ink);\n      border-radius: 999px; padding: 6px 14px; font: 600 12px/1.3 var(--sans);\n      cursor: pointer; white-space: nowrap; transition: background .15s, border-color .15s;\n      box-shadow: 0 1px 3px rgba(30,35,32,.04);\n    }\n    .btn:hover { background: var(--sub); border-color: rgba(30,35,32,.18); }\n    .btn:disabled { opacity: .55; cursor: wait; }\n\n    .nav {\n      display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 4px;\n      background: var(--card); border: 1px solid rgba(30,35,32,.07);\n      border-radius: 999px; padding: 5px; margin: 14px 0 16px;\n      box-shadow: 0 2px 10px rgba(30,35,32,.03);\n    }\n    .tab-btn {\n      appearance: none; border: 0; background: transparent; color: var(--muted);\n      border-radius: 999px; padding: 8px 10px; font: 600 13px/1.2 var(--sans);\n      cursor: pointer; white-space: nowrap; transition: background .15s, color .15s;\n    }\n    .tab-btn:hover { color: var(--ink); }\n    .tab-btn.active { background: var(--ink); color: #FFF; }\n    .tab-panel { display: none; }\n    .tab-panel.active { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }\n\n    /* Cards & Pills */\n    .card {\n      background: var(--card); border: 1px solid rgba(30,35,32,.07);\n      border-radius: 20px; padding: 20px 22px; min-width: 0;\n      box-shadow: 0 2px 12px rgba(30,35,32,.035);\n    }\n    .sec-head {\n      display: flex; align-items: flex-start; justify-content: space-between;\n      gap: 10px; flex-wrap: wrap; margin-bottom: 14px;\n    }\n    .sec-title { margin: 0; font-size: 16px; font-weight: 700; letter-spacing: -0.012em; color: var(--ink); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n    .sec-sub { margin: 3px 0 0; font-size: 12px; color: var(--muted); }\n    .pill {\n      display: inline-flex; align-items: center; gap: 4px;\n      padding: 3px 10px; border-radius: 999px; font-size: 11px; font-weight: 600;\n      line-height: 1.35; white-space: nowrap;\n    }\n    .tone-sage { background: var(--sage-bg); color: var(--sage); }\n    .tone-terra { background: var(--terra-bg); color: var(--terra); }\n    .tone-ochre { background: var(--ochre-bg); color: var(--ochre); }\n    .tone-slate { background: var(--slate-bg); color: var(--slate); }\n    .chg-up { background: var(--up-bg); color: var(--up); }\n    .chg-down { background: var(--down-bg); color: var(--down); }\n    .chg-flat { background: var(--sub); color: var(--muted); }\n\n    .f-row { display: flex; flex-wrap: wrap; gap: 6px; }\n    .f-btn {\n      appearance: none; border: 1px solid var(--border); background: var(--card); color: var(--muted);\n      border-radius: 999px; padding: 5px 12px; font: 600 12px/1.3 var(--sans); cursor: pointer;\n    }\n    .f-btn.active { background: var(--ink); color: #FFF; border-color: var(--ink); }\n\n    .grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n    .grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n    .grid-cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }\n\n    /* Hero Brief */\n    .hero-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }\n    .hero-time { font-size: 12px; color: var(--muted); }\n    .headline { margin: 0 0 12px; font-size: 17.5px; font-weight: 700; line-height: 1.45; letter-spacing: -0.015em; color: #161A18; text-wrap: pretty; }\n    .warm-box {\n      background: var(--warm); border: 1px solid var(--warm-bd); border-left: 2.5px solid #CCA052;\n      border-radius: 0 10px 10px 0; padding: 11px 14px; font-size: 12.5px; line-height: 1.68; color: #3B403D;\n    }\n    .warm-box strong { color: var(--ochre); font-weight: 700; }\n\n    .kpi-box {\n      background: var(--sub); border: 1px solid var(--border); border-radius: 12px;\n      padding: 11px 13px; display: flex; flex-direction: column; justify-content: space-between; gap: 7px; min-width: 0;\n    }\n    .kpi-row { display: flex; align-items: center; justify-content: space-between; gap: 6px; }\n    .kpi-lbl { font-size: 11.5px; color: var(--muted); font-weight: 600; }\n    .kpi-val { font-size: 15px; font-weight: 700; color: var(--ink); font-family: var(--mono); }\n    .kpi-chg { font-size: 10.5px; font-weight: 700; padding: 1px 6px; border-radius: 999px; font-family: var(--mono); }\n    .bar-bg { width: 100%; height: 6px; border-radius: 999px; background: #E9E4D8; overflow: hidden; }\n    .bar-fill { height: 100%; border-radius: 999px; transition: width .25s ease; }\n    .kpi-note { font-size: 11px; color: var(--muted); line-height: 1.45; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n    .kpi-mini + .kpi-mini { padding-top: 6px; border-top: 1px dashed var(--border); }\n\n    .blue-box {\n      background: var(--blue-bg); border: 1px solid var(--blue-bd); border-radius: 12px;\n      padding: 11px 13px; display: flex; flex-direction: column; gap: 4px; min-width: 0;\n    }\n    .blue-lbl { font-size: 11px; font-weight: 700; color: var(--slate); }\n    .blue-txt { font-size: 12px; font-weight: 600; line-height: 1.55; color: var(--ink); overflow-wrap: anywhere; }\n\n    .drawer-row { display: flex; flex-wrap: wrap; gap: 10px 18px; margin-top: 12px; padding-top: 10px; border-top: 1px solid rgba(30,35,32,.06); }\n    details.quiet { font-size: 12px; color: var(--muted); flex: 1 1 260px; }\n    details.quiet summary { cursor: pointer; font-weight: 600; color: var(--muted); user-select: none; }\n    details.quiet summary:hover { color: var(--ink); }\n    details.quiet[open] summary { color: var(--ink); margin-bottom: 8px; }\n    .drawer-body {\n      background: var(--sub); border: 1px solid var(--border); border-radius: 12px;\n      padding: 11px 13px; color: var(--ink); font-size: 12.5px; line-height: 1.65;\n    }\n    .drawer-body p { margin: 0; }\n    .drawer-body p + p { margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--border); }\n\n    /* Ticker Strip */\n    .ticker-strip {\n      display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: thin;\n    }\n    .ticker-item {\n      flex: 0 0 auto; display: inline-flex; align-items: center; gap: 7px;\n      background: var(--sub); border: 1px solid var(--border); border-radius: 12px;\n      padding: 7px 11px; font-size: 12px;\n    }\n    .ticker-item strong { font-weight: 700; color: var(--ink); }\n    .ticker-item .px { font-family: var(--mono); color: #3D4540; }\n    .ticker-item .pct { font-family: var(--mono); font-size: 11px; font-weight: 700; padding: 1px 6px; border-radius: 6px; }\n\n    /* Charts Container */\n    .chart-box {\n      background: var(--sub); border: 1px solid var(--border); border-radius: 14px;\n      padding: 14px 16px;\n    }\n    .chart-box h3 { margin: 0 0 10px; font-size: 13px; font-weight: 700; color: var(--ink); }\n    .chart-box svg { display: block; width: 100%; height: auto; }\n    .legend-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }\n    .legend-btn {\n      appearance: none; border: 1px solid var(--border); background: var(--card); color: var(--ink);\n      border-radius: 999px; padding: 3px 10px; font: 600 11.5px/1.4 var(--sans); cursor: pointer;\n      display: inline-flex; align-items: center; gap: 5px;\n    }\n    .legend-btn[aria-pressed=\"false\"] { opacity: .45; text-decoration: line-through; }\n    .legend-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }\n\n    /* Momentum Ranking Bars */\n    .mom-list { display: grid; gap: 8px; }\n    .mom-row {\n      appearance: none; border: 1px solid transparent; background: transparent; width: 100%;\n      display: grid; grid-template-columns: 196px minmax(0, 1fr) 44px; gap: 10px; align-items: center;\n      padding: 4px 6px; border-radius: 10px; cursor: pointer; text-align: left; font: inherit;\n    }\n    .mom-row:hover, .mom-row[aria-pressed=\"true\"] { background: rgba(46,111,94,.08); border-color: rgba(46,111,94,.25); }\n    .mom-lbl { font-size: 12.5px; font-weight: 700; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n    .mom-track { height: 14px; border-radius: 999px; background: #EAE6DC; overflow: hidden; }\n    .mom-fill { height: 100%; border-radius: 999px; transition: width .3s ease; }\n    .mom-val { font-family: var(--mono); font-size: 12.5px; font-weight: 700; text-align: right; color: var(--ink); }\n\n    /* Mainline Cards & Vertical Timeline */\n    .ml-stack { display: grid; gap: 14px; margin-top: 14px; }\n    .m-card {\n      background: var(--card); border: 1px solid rgba(30,35,32,.08); border-radius: 16px;\n      padding: 16px 18px; box-shadow: 0 1px 4px rgba(30,35,32,.025);\n      transition: border-color .15s, box-shadow .15s;\n    }\n    .m-card.selected { border-color: var(--sage); box-shadow: 0 0 0 2px rgba(46,111,94,.16); }\n    .m-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; margin-bottom: 10px; }\n    .m-title {\n      appearance: none; border: 0; background: transparent; padding: 0; text-align: left;\n      font: 700 15.5px/1.38 var(--sans); letter-spacing: -0.012em; color: var(--ink); cursor: pointer;\n    }\n    .m-title:hover { color: var(--sage); }\n    .m-meta { font-size: 11.5px; color: var(--muted); margin-top: 2px; }\n\n    .chain-timeline { position: relative; padding-left: 18px; margin: 10px 0 12px; display: grid; gap: 7px; }\n    .chain-timeline::before {\n      content: \"\"; position: absolute; left: 5px; top: 8px; bottom: 8px; width: 1.5px;\n      background: linear-gradient(180deg, var(--sage) 0%, #D9D3C7 100%);\n    }\n    .chain-node { position: relative; display: flex; align-items: baseline; gap: 8px; font-size: 13px; line-height: 1.58; color: #2C322F; }\n    .chain-node::before {\n      content: \"\"; position: absolute; left: -16px; top: 6px; width: 7px; height: 7px; border-radius: 50%;\n      background: var(--card); border: 1.5px solid #B9B2A5;\n    }\n    .chain-node.is-first::before {\n      background: var(--sage); border-color: var(--sage); box-shadow: 0 0 0 3px rgba(46,111,94,.18);\n    }\n    .chain-step-tag {\n      flex-shrink: 0; font-family: var(--mono); font-size: 10.5px; font-weight: 700;\n      color: var(--sage); background: var(--sage-bg); padding: 1px 6px; border-radius: 5px;\n    }\n    .chain-node:not(.is-first) .chain-step-tag { color: var(--muted); background: var(--sub); border: 1px solid var(--border); }\n\n    .stock-row {\n      display: flex; align-items: center; justify-content: space-between; gap: 10px;\n      flex-wrap: wrap; margin: 10px 0 12px;\n    }\n    .stock-tags { display: flex; flex-wrap: wrap; gap: 6px; }\n    .stock-tag {\n      display: inline-flex; align-items: center; gap: 5px;\n      background: var(--sub); border: 1px solid var(--border); border-radius: 7px;\n      padding: 3px 8px; font-size: 11.5px;\n    }\n    .stock-tag strong { font-family: var(--mono); font-size: 11.5px; color: var(--ink); }\n    .stock-tag .pct { font-family: var(--mono); font-size: 11px; font-weight: 700; }\n    .m-anchor { font-size: 11.5px; color: var(--muted); font-family: var(--mono); display: flex; align-items: center; gap: 8px; }\n\n    .m-watch {\n      margin-top: 11px; padding-top: 10px; border-top: 1px solid rgba(30,35,32,.06);\n      display: flex; justify-content: space-between; align-items: flex-start; gap: 12px;\n      font-size: 12px; color: var(--muted); line-height: 1.58;\n    }\n    .m-watch strong { color: var(--ink); }\n    a.src-link { color: var(--slate); text-decoration: none; font-weight: 600; white-space: nowrap; flex-shrink: 0; }\n    a.src-link:hover { text-decoration: underline; }\n\n    .m-more { margin-top: 8px; }\n    .m-more ul { margin: 6px 0; padding-left: 18px; }\n    .m-more li + li { margin-top: 4px; }\n\n    /* Setup Cards & Ladder */\n    .setup-card {\n      background: var(--card); border: 1px solid rgba(30,35,32,.08); border-radius: 16px;\n      padding: 14px 15px; display: flex; flex-direction: column; gap: 10px; min-width: 0;\n      box-shadow: 0 1px 4px rgba(30,35,32,.025); scroll-margin-top: 72px;\n    }\n    .setup-card:focus { outline: 2px solid var(--sage); outline-offset: 2px; }\n    .setup-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }\n    .setup-sym { font-family: var(--mono); font-size: 15px; font-weight: 700; color: var(--ink); }\n    .mini-tag { font-family: var(--mono); font-size: 10px; font-weight: 700; padding: 1px 6px; border-radius: 5px; background: var(--sub); border: 1px solid var(--border); color: var(--muted); }\n    .setup-val-line { font-size: 11px; color: var(--muted); margin-top: 2px; }\n    .setup-nums {\n      display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px;\n      background: var(--sub); border: 1px solid var(--border); border-radius: 11px;\n      padding: 8px 6px; text-align: center;\n    }\n    .setup-nums span { display: block; font-size: 10.5px; color: var(--muted); }\n    .setup-nums strong { display: block; font-family: var(--mono); font-size: 13px; color: var(--ink); margin-top: 2px; }\n    .ladder-labels { display: flex; justify-content: space-between; font-size: 10.5px; font-family: var(--mono); color: var(--muted); margin-bottom: 4px; gap: 4px; }\n    .ladder-track {\n      position: relative; height: 6px; border-radius: 999px;\n      background: linear-gradient(90deg, #F3D5D0 0%, #EAE5DA 50%, #CDE5DD 100%);\n    }\n    .ladder-pin {\n      position: absolute; top: 50%; width: 10px; height: 10px; border-radius: 50%;\n      background: var(--ink); border: 2px solid #FFF; box-shadow: 0 1px 3px rgba(0,0,0,.25);\n      transform: translate(-50%, -50%);\n    }\n    .setup-foot { padding-top: 8px; border-top: 1px solid rgba(30,35,32,.06); font-size: 11.5px; color: var(--muted); line-height: 1.55; }\n\n    /* Candidates, Matrix, Macro, News */\n    .cand-card {\n      background: var(--card); border: 1px solid rgba(30,35,32,.08); border-radius: 16px;\n      padding: 15px 16px; display: flex; flex-direction: column; gap: 7px; min-width: 0;\n    }\n    .cand-card.active-card { border-color: var(--sage); box-shadow: 0 0 0 2px rgba(46,111,94,.16); }\n    .cand-title { margin: 0; font-size: 14.5px; font-weight: 700; color: var(--ink); }\n    .cand-rule { padding-top: 8px; border-top: 1px solid rgba(30,35,32,.06); font-size: 11.5px; color: var(--muted); }\n\n    .table-scroll { overflow-x: auto; }\n    table.matrix { width: 100%; border-collapse: separate; border-spacing: 5px; font-size: 12px; text-align: center; }\n    table.matrix th { font-weight: 700; color: var(--ink); padding: 6px 4px; font-size: 11.5px; }\n    table.matrix td { padding: 9px 6px; border-radius: 9px; font-family: var(--mono); font-weight: 700; }\n\n    .link-card {\n      background: var(--card); border: 1px solid rgba(30,35,32,.08); border-radius: 16px;\n      padding: 15px 16px; display: flex; flex-direction: column; gap: 8px;\n    }\n    .link-signal { padding-top: 8px; border-top: 1px solid rgba(30,35,32,.06); font-size: 12px; color: var(--slate); }\n\n    .macro-card {\n      background: var(--card); border: 1px solid rgba(30,35,32,.07); border-radius: 20px;\n      padding: 18px 20px; box-shadow: 0 2px 10px rgba(30,35,32,.03);\n      display: grid; gap: 10px; scroll-margin-top: 72px;\n    }\n    .macro-card.active-card { border-color: var(--sage); box-shadow: 0 0 0 2px rgba(46,111,94,.16); }\n    .gauge-labels { display: flex; justify-content: space-between; font-size: 11px; color: var(--muted); margin-bottom: 4px; }\n    .gauge-labels strong { color: var(--ink); font-family: var(--mono); }\n    .macro-kpi { background: var(--sub); border: 1px solid var(--border); border-radius: 12px; padding: 10px 12px; }\n    .macro-kpi-top { display: flex; justify-content: space-between; gap: 6px; font-size: 11px; color: var(--muted); margin-bottom: 3px; }\n    .macro-kpi-val { font-family: var(--mono); font-size: 15px; font-weight: 700; color: var(--ink); }\n\n    .feed-item {\n      background: var(--sub); border: 1px solid var(--border); border-radius: 14px;\n      padding: 14px 16px; display: grid; gap: 6px;\n    }\n    .feed-meta { display: flex; justify-content: space-between; align-items: center; gap: 8px; font-size: 11.5px; color: var(--muted); flex-wrap: wrap; }\n    .feed-title { font-size: 14px; font-weight: 700; color: var(--ink); line-height: 1.42; }\n    .feed-body { font-size: 12.5px; color: #3B403D; line-height: 1.65; }\n\n    .empty-box {\n      background: var(--sub); border: 1px dashed var(--border); border-radius: 14px;\n      padding: 20px 14px; text-align: center; color: var(--muted); font-size: 12.5px;\n    }\n\n    @media (max-width: 840px) {\n      .grid-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n    }\n    @media (max-width: 640px) {\n      .wrap { padding: 14px 12px 40px; }\n      .card { padding: 15px 14px; border-radius: 16px; }\n      .grid-3, .grid-2, .grid-cards { grid-template-columns: 1fr; }\n      .headline { font-size: 16px; }\n      .nav {\n        position: sticky; top: 6px; z-index: 10;\n        display: grid; grid-template-columns: repeat(5, minmax(0, 1fr));\n        padding: 4px; gap: 2px;\n      }\n      .tab-btn { padding: 7px 2px; font-size: 11px; letter-spacing: -0.02em; }\n      .mom-row { grid-template-columns: 128px minmax(0, 1fr) 38px; gap: 8px; }\n      .m-head { flex-wrap: wrap; }\n      .m-watch { flex-direction: column; gap: 6px; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"wrap\">\n    <header class=\"hdr\">\n      <div class=\"hdr-top\">\n        <div class=\"hdr-left\">\n          <h1>美股交易链条观察</h1>\n          <span class=\"sync-pill\" id=\"liveSyncPill\" role=\"status\">\n            <span class=\"sync-dot\" id=\"liveSyncDot\"></span>\n            <span id=\"liveTimeText\">同步中...</span>\n          </span>\n        </div>\n        <div class=\"btn-row\">\n          <button type=\"button\" class=\"btn\" id=\"btnColorMode\">红涨绿跌</button>\n          <button type=\"button\" class=\"btn\" id=\"btnRefreshAll\">刷新</button>\n        </div>\n      </div>\n      <p class=\"subtitle\">挖掘市场交易主线 · 估值安全垫与回撤雷达 · 追踪替补升降级 · 读懂跨资产联动</p>\n    </header>\n\n    <nav class=\"nav\" id=\"mainNav\" aria-label=\"主视图切换\">\n      <button type=\"button\" class=\"tab-btn active\" data-tab=\"chains\" aria-pressed=\"true\">主线与传导</button>\n      <button type=\"button\" class=\"tab-btn\" data-tab=\"candidates\" aria-pressed=\"false\">替补与轮动</button>\n      <button type=\"button\" class=\"tab-btn\" data-tab=\"linkage\" aria-pressed=\"false\">跨资产联动</button>\n      <button type=\"button\" class=\"tab-btn\" data-tab=\"macro\" aria-pressed=\"false\">宏观与日程</button>\n      <button type=\"button\" class=\"tab-btn\" data-tab=\"news\" aria-pressed=\"false\">中文快讯</button>\n    </nav>\n\n    <main>\n      <section id=\"panel-chains\" class=\"tab-panel active\">\n        <div id=\"heroContainer\" class=\"card\">\n          <div class=\"empty-box\">正在加载全市场主线研判...</div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"sec-head\" style=\"margin-bottom:10px;\">\n            <h2 class=\"sec-title\" style=\"font-size:14px;\">核心标的实时锚</h2>\n            <span id=\"quoteRibbonTime\" class=\"muted\" style=\"font-size:11.5px;\">等待行情</span>\n          </div>\n          <div id=\"quoteRibbon\" class=\"ticker-strip\" role=\"region\" aria-label=\"核心标的实时锚\"></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <div>\n              <h2 class=\"sec-title\">每日主线动能与传导链（M1–M5）</h2>\n              <p class=\"sec-sub\">点击柱状条或主线标题，可联动筛选下方估值雷达标的</p>\n            </div>\n            <button type=\"button\" class=\"pill tone-slate\" id=\"clearMainlinePill\" style=\"border:0;cursor:pointer;\">全部 5 条主线</button>\n          </div>\n          <div class=\"chart-box\">\n            <div id=\"mainlineMomentum\" class=\"mom-list\"></div>\n          </div>\n          <details class=\"quiet\" id=\"mainlineTrend\" style=\"margin-top:10px;\">\n            <summary>查看近 11 期归一化走势（期初 = 100）</summary>\n            <div class=\"chart-box\" style=\"margin-top:8px;\">\n              <div id=\"mlOverviewSvg\"></div>\n              <div id=\"mainlineTrendLegend\" class=\"legend-row\"></div>\n            </div>\n          </details>\n          <div id=\"mainlinesContainer\" class=\"ml-stack\"></div>\n        </div>\n\n        <section class=\"card\" id=\"setupRadar\" aria-labelledby=\"setupHeading\">\n          <div class=\"sec-head\">\n            <div>\n              <h2 class=\"sec-title\" id=\"setupHeading\" tabindex=\"-1\">\n                <span class=\"pill tone-sage\">观察标的</span>估值安全垫 × 回撤雷达\n              </h2>\n              <p class=\"sec-sub\" id=\"setupCoverage\" role=\"status\">正在读取估值与回撤数据</p>\n            </div>\n            <div class=\"f-row\" id=\"setupCategories\" aria-label=\"按观察类型筛选\">\n              <button type=\"button\" class=\"f-btn active\" data-setup-category=\"all\">全部</button>\n              <button type=\"button\" class=\"f-btn\" data-setup-category=\"dip\">深度回撤</button>\n              <button type=\"button\" class=\"f-btn\" data-setup-category=\"hedge\">防御对照</button>\n              <button type=\"button\" class=\"f-btn\" data-setup-category=\"spec\">高波观察</button>\n              <button type=\"button\" class=\"f-btn\" data-setup-category=\"avoid\">风险警示</button>\n              <button type=\"button\" class=\"f-btn\" data-setup-category=\"watch\">待观察</button>\n            </div>\n          </div>\n          <div id=\"setupPlot\" class=\"chart-box\" style=\"margin-bottom:14px;\"></div>\n          <div id=\"setupCards\" class=\"grid-cards\"></div>\n        </section>\n      </section>\n\n      <section id=\"panel-candidates\" class=\"tab-panel\">\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <div>\n              <h2 class=\"sec-title\">潜力替补主线池 · 升降级判定</h2>\n              <p class=\"sec-sub\">追踪连续走强的晋级方向与弱化淘汰方向（C1–C6）</p>\n            </div>\n          </div>\n          <div class=\"f-row\" id=\"candidateFilterBar\" style=\"margin-bottom:14px;\">\n            <button type=\"button\" class=\"f-btn active\" data-cfilter=\"all\">全部 (0)</button>\n            <button type=\"button\" class=\"f-btn\" data-cfilter=\"upgrade\">↑ 准备升级 (0)</button>\n            <button type=\"button\" class=\"f-btn\" data-cfilter=\"watch\">● 强化跟踪 (0)</button>\n            <button type=\"button\" class=\"f-btn\" data-cfilter=\"demote\">↓ 弱化/淘汰 (0)</button>\n          </div>\n          <div class=\"grid-2\" style=\"margin-bottom:14px;\">\n            <div class=\"chart-box\">\n              <h3>动量四象限（20日 vs 5日涨跌幅）</h3>\n              <div id=\"candQuadSvg\"></div>\n            </div>\n            <div class=\"chart-box\">\n              <h3>5日（深色）vs 20日（浅色）涨跌对比</h3>\n              <div id=\"candBarSvg\"></div>\n            </div>\n          </div>\n          <div id=\"candidatesContainer\" class=\"grid-2\"></div>\n        </div>\n      </section>\n\n      <section id=\"panel-linkage\" class=\"tab-panel\">\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <div>\n              <h2 class=\"sec-title\">跨资产相关性热力矩阵</h2>\n              <p class=\"sec-sub\">颜色随顶部「红涨绿跌」模式实时联动 · +1 为同向，−1 为反向</p>\n            </div>\n          </div>\n          <div class=\"table-scroll\" id=\"corrMatrixWrap\"></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <h2 class=\"sec-title\">四大核心联动关系（图表 + 白话拆解）</h2>\n          </div>\n          <div class=\"chart-box\" id=\"linkageBarSvg\" style=\"margin-bottom:14px;\"></div>\n          <div id=\"linkageStoriesContainer\" class=\"grid-2\"></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <h2 class=\"sec-title\">30 日跨资产剪刀差走势（累计收益 %）</h2>\n          </div>\n          <div class=\"chart-box\">\n            <div id=\"linkageTrendSvg\"></div>\n            <div id=\"linkageTrendLegend\" class=\"legend-row\"></div>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"panel-macro\" class=\"tab-panel\">\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <div>\n              <h2 class=\"sec-title\">宏观与产业五维顺风雷达</h2>\n              <p class=\"sec-sub\">外圈 100 = 顺风宽松，内圈 0 = 高压逆风；点击维度按钮跳转到详情卡片</p>\n            </div>\n            <span id=\"radarRegime\" class=\"pill tone-slate\">读取中</span>\n          </div>\n          <div class=\"chart-box\" id=\"macroRadarSvg\" style=\"text-align:center;\"></div>\n          <div id=\"radarDimensions\" class=\"f-row\" style=\"margin-top:12px;\"></div>\n          <p id=\"radarComparison\" class=\"sec-sub\" style=\"margin-top:8px;\"></p>\n        </div>\n\n        <div id=\"macroCardsContainer\" style=\"display:grid;gap:14px;\"></div>\n\n        <div class=\"card\">\n          <div class=\"sec-head\"><h2 class=\"sec-title\">关键交易日程与宏观闸口</h2></div>\n          <div id=\"calendarContainer\" style=\"display:grid;gap:10px;\"></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <h2 class=\"sec-title\">主线演进与复盘日志</h2>\n            <button type=\"button\" class=\"btn\" id=\"toggleHistory\" hidden>展开全部</button>\n          </div>\n          <div id=\"historyLog\" style=\"display:grid;gap:10px;\"></div>\n        </div>\n      </section>\n\n      <section id=\"panel-news\" class=\"tab-panel\">\n        <div class=\"card\">\n          <div class=\"sec-head\">\n            <div>\n              <h2 class=\"sec-title\">美股与宏观中文快讯流</h2>\n              <p class=\"sec-sub\">实时聚合最新中文快讯与跨市场异动线索</p>\n            </div>\n            <button type=\"button\" class=\"btn\" id=\"btnRefreshNews\">刷新快讯</button>\n          </div>\n          <div id=\"newsContainer\" style=\"display:grid;gap:10px;\">\n            <div class=\"empty-box\">点击或等待加载最新快讯...</div>\n          </div>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <script>\n    (function () {\n      \"use strict\";\n\n      const STORE = {\n        state: null,\n        live: null,\n        news: null,\n        stateSource: \"none\",\n        liveSource: \"none\",\n        stateBusy: false,\n        liveBusy: false,\n        newsBusy: false,\n        stateErr: \"\",\n        liveErr: \"\",\n        newsErr: \"\",\n        activeTab: \"chains\",\n        candFilter: \"all\",\n        mainlineFilter: \"\",\n        setupCategory: \"all\",\n        historyExpanded: false,\n        hiddenSeries: { overview: new Set(), linkage: new Set() },\n      };\n\n      const PALETTE = [\"#2E6F5E\", \"#B87D2B\", \"#47627A\", \"#B84A39\", \"#74629B\"];\n      const ASSET_CN = {\n        SPY: \"标普500\", QQQ: \"纳指100\", TLT: \"20年美债\", GLD: \"黄金\", NVDA: \"英伟达\", BTC: \"比特币\",\n        \"BTC-USD\": \"比特币\", \"ES=F\": \"标普期货\", \"NQ=F\": \"纳指期货\", \"GC=F\": \"黄金\", \"SI=F\": \"白银\",\n        \"HG=F\": \"铜\", \"BZ=F\": \"布油\", \"CL=F\": \"美油\", \"^VIX\": \"恐慌指数\", \"^TNX\": \"10Y美债\",\n        \"^MOVE\": \"债市波动率\", \"^GSPC\": \"标普500\", \"^IXIC\": \"纳指\", \"DX-Y.NYB\": \"美元指数\",\n        \"ASML.AS\": \"阿斯麦欧股\", \"2330.TW\": \"台积电台股\", \"000660.KS\": \"SK海力士\", \"005930.KS\": \"三星电子\",\n        TSM: \"台积电\", AVGO: \"博通\", ASML: \"阿斯麦\", SMH: \"半导体ETF\", SOXX: \"半导体ETF\",\n        XLE: \"能源ETF\", XLP: \"必选消费\", XLU: \"公用事业\", XLF: \"金融ETF\", ITB: \"房屋建筑\",\n        LMT: \"洛克希德马丁\", AAPL: \"苹果\", MSTR: \"微策略\", COIN: \"Coinbase\", CRWV: \"CoreWeave\",\n        IREN: \"IREN\", NBIS: \"Nebius\", LITE: \"Lumentum\", HYG: \"高收益债\", LQD: \"投资级债\",\n      };\n      const RAW_CODE_REPL = [\n        [/\\bNQ=F\\b/g, \"纳指期货\"], [/\\bES=F\\b/g, \"标普期货\"], [/\\bGC=F\\b/g, \"黄金\"],\n        [/\\bSI=F\\b/g, \"白银\"], [/\\bHG=F\\b/g, \"铜\"], [/\\bBZ=F\\b/g, \"布油\"], [/\\bCL=F\\b/g, \"美油\"],\n        [/\\bJPY=X\\b/g, \"美元/日元\"], [/DX-Y\\.NYB/g, \"美元指数\"], [/\\bBTC-USD\\b/g, \"比特币\"],\n        [/\\bASML\\.AS\\b/g, \"阿斯麦欧股\"], [/\\b2330\\.TW\\b/g, \"台积电台股\"],\n        [/\\b000660\\.KS\\b/g, \"SK海力士\"], [/\\b005930\\.KS\\b/g, \"三星电子\"],\n        [/\\b000001\\.SS\\b/g, \"上证指数\"], [/\\^GSPC/g, \"标普500\"], [/\\^IXIC/g, \"纳指\"],\n        [/\\^VIX/g, \"VIX\"], [/\\^TNX/g, \"10Y美债\"], [/\\^MOVE/g, \"债市波动率\"],\n        [/\\^N225/g, \"日经225\"], [/\\^KS11/g, \"韩国KOSPI\"], [/\\^TWII/g, \"台湾加权\"],\n        [/\\^HSI/g, \"恒生指数\"], [/\\^GDAXI/g, \"德国DAX\"], [/\\^STOXX50E/g, \"欧洲斯托克50\"],\n      ];\n      const PROSE_TICKER_REPL = [\n        [\"NVDA\", \"英伟达\", [\"英伟达\"]], [\"AVGO\", \"博通\", [\"博通\"]], [\"TSM\", \"台积电\", [\"台积电\"]],\n        [\"ASML\", \"阿斯麦\", [\"阿斯麦\"]], [\"SMH\", \"半导体ETF\", [\"半导体\"]], [\"SOXX\", \"半导体ETF\", [\"半导体\"]],\n        [\"TLT\", \"长债ETF\", [\"长债\", \"美债\"]], [\"SPY\", \"标普500\", [\"标普\"]], [\"QQQ\", \"纳指100\", [\"纳指\"]],\n        [\"XLE\", \"能源ETF\", [\"能源\"]], [\"XLP\", \"必选消费\", [\"必选消费\", \"防御消费\", \"必需消费\"]],\n        [\"XLU\", \"公用事业\", [\"公用事业\", \"公用电力\"]], [\"XLF\", \"金融ETF\", [\"金融\"]],\n        [\"ITB\", \"房屋建筑\", [\"房屋建筑\", \"地产建筑\"]], [\"GLD\", \"黄金ETF\", [\"黄金\"]],\n        [\"HYG\", \"高收益债\", [\"高收益债\"]], [\"LQD\", \"投资级债\", [\"投资级债\"]],\n        [\"LMT\", \"洛克希德马丁\", [\"洛克希德\"]], [\"AAPL\", \"苹果\", [\"苹果\"]],\n        [\"MSTR\", \"微策略\", [\"微策略\", \"Strategy\"]], [\"COIN\", \"Coinbase\", [\"Coinbase\"]],\n        [\"KOSPI\", \"韩股\", [\"韩股\", \"韩国\"]], [\"DXY\", \"美元指数\", [\"美元指数\", \"美元\"]],\n        [\"MOVE\", \"债市波动率\", [\"波动率\"]],\n      ];\n\n      function esc(v) {\n        return v === null || v === undefined ? \"\" : String(v)\n          .replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\")\n          .replace(/\"/g, \"&quot;\").replace(/'/g, \"&#39;\");\n      }\n\n      function safeUrl(url) {\n        if (typeof url !== \"string\" || !url.trim()) return \"\";\n        try {\n          const u = new URL(url.trim());\n          return u.protocol === \"http:\" || u.protocol === \"https:\" ? u.href : \"\";\n        } catch (_) { return \"\"; }\n      }\n\n      function numOrNull(v) {\n        return typeof v === \"number\" && Number.isFinite(v) ? v : null;\n      }\n\n      function humanizeCopy(val) {\n        if (val === null || val === undefined) return \"\";\n        let s = String(val)\n          .replace(/^\\[First_seen:[^\\]]*\\]\\s*/g, \"\")\n          .replace(/[（(](?:HOLIDAY_LOCK|INTRADAY_LOCK|POST_CLOSE_SETTLE|PRE_MARKET|OFF_HOURS)[）)]/g, \"\")\n          .replace(/对应\\s*[MC]\\d(?:\\/[MC]\\d)*(?:\\s*[，,、。])?/g, \"\")\n          .replace(/\\b(\\d+)D(?=\\s*[+-]?\\d|\\s*[均涨跌回收跑走强弱])/g, \"近$1日\");\n        for (const [re, cn] of RAW_CODE_REPL) {\n          const cnNorm = cn.replace(/\\s+/g, \"\");\n          s = s.replace(re, (match, offset, full) => {\n            const before = full.slice(Math.max(0, offset - cn.length - 6), offset).replace(/\\s+/g, \"\");\n            if (before.includes(cnNorm)) return match;\n            return cn;\n          });\n        }\n        for (const [sym, cn, aliases] of PROSE_TICKER_REPL) {\n          const re = new RegExp(`(^|[^A-Za-z0-9_.])(${sym})(?![A-Za-z0-9_.])`, \"g\");\n          s = s.replace(re, (match, pre, tok, offset, full) => {\n            const tokPos = offset + pre.length;\n            const prevCh = full[tokPos - 1] || \"\";\n            if (prevCh === \"(\" || prevCh === \"（\") return match;\n            const before = full.slice(Math.max(0, tokPos - 10), tokPos).replace(/\\s+/g, \"\");\n            if (aliases.some(a => before.includes(a))) return pre === \" \" ? \"\" : pre;\n            return pre + cn;\n          });\n        }\n        return s\n          .replace(/[（(]\\s*\\^?(?:TNX|VIX|MOVE)\\s*[）)]/g, \"\")\n          .replace(/[ \\t]+([、，。；：！？）】」])/g, \"$1\")\n          .replace(/([、，。；：！？（【「])[ \\t]+/g, \"$1\")\n          .replace(/([\\u4e00-\\u9fff])([A-Za-z0-9$€£¥]|[+-](?=\\d))/g, \"$1 $2\")\n          .replace(/([A-Za-z0-9%])([\\u4e00-\\u9fff])/g, \"$1 $2\")\n          .replace(/\\s{2,}/g, \" \")\n          .trim();\n      }\n\n      function fmtHtml(val) { return esc(humanizeCopy(val)); }\n      function toneCls(t) { return [\"sage\", \"terra\", \"ochre\", \"slate\"].includes(t) ? \"tone-\" + t : \"tone-slate\"; }\n      function chgCls(v) { const n = numOrNull(v); return n === null || n === 0 ? \"chg-flat\" : n > 0 ? \"chg-up\" : \"chg-down\"; }\n      function fmtChg(v) { const n = numOrNull(v); return n === null ? \"--\" : (n > 0 ? \"+\" : \"\") + n.toFixed(2) + \"%\"; }\n      function fmtPrice(sym, p) {\n        const n = numOrNull(p);\n        if (n === null) return \"--\";\n        if (sym === \"^TNX\") return n.toFixed(2) + \"%\";\n        if (sym === \"^VIX\" || sym === \"^MOVE\") return n.toFixed(2);\n        if (sym === \"BTC-USD\") return \"$\" + n.toLocaleString(\"en-US\", { maximumFractionDigits: 0 });\n        if (n >= 1000) return \"$\" + n.toLocaleString(\"en-US\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n        return \"$\" + n.toFixed(2);\n      }\n      function fmtLvl(v) {\n        const n = numOrNull(v);\n        if (n === null) return \"--\";\n        return Math.abs(n - Math.round(n)) < 1e-6 ? n.toFixed(0) : n.toFixed(2).replace(/0$/, \"\");\n      }\n      function cssVar(name) { return getComputedStyle(document.body).getPropertyValue(name).trim(); }\n      function quoteMap() {\n        const m = Object.create(null);\n        for (const q of (STORE.live?.quotes || [])) if (q?.sym) m[q.sym] = q;\n        return m;\n      }\n      function parseStocks(str) {\n        return String(str || \"\").split(\",\").map(s => s.trim()).filter(Boolean).map(p => {\n          const i = p.indexOf(\":\");\n          return i < 0 ? { sym: p, name: ASSET_CN[p] || p } : { sym: p.slice(0, i).trim(), name: p.slice(i + 1).trim() };\n        });\n      }\n      function sessionCn(s) {\n        return { PRE_MARKET: \"盘前\", INTRADAY: \"盘中\", AFTER_HOURS: \"盘后\", HOLIDAY: \"休市\", OFF_HOURS: \"闭市\" }[s] || \"已同步\";\n      }\n\n      /* Color Convention Toggle */\n      function initColorMode() {\n        const greenUp = localStorage.getItem(\"desk-color-mode\") === \"green-up\";\n        document.body.classList.toggle(\"green-up\", greenUp);\n        const btn = document.getElementById(\"btnColorMode\");\n        btn.textContent = greenUp ? \"绿涨红跌\" : \"红涨绿跌\";\n        btn.onclick = () => {\n          const next = !document.body.classList.contains(\"green-up\");\n          document.body.classList.toggle(\"green-up\", next);\n          localStorage.setItem(\"desk-color-mode\", next ? \"green-up\" : \"red-up\");\n          btn.textContent = next ? \"绿涨红跌\" : \"红涨绿跌\";\n          if (STORE.state) { renderCandidateCharts(); renderLinkage(); }\n        };\n      }\n\n      /* Sync Status Pill */\n      function updateSyncPill() {\n        const pill = document.getElementById(\"liveSyncPill\");\n        const dot = document.getElementById(\"liveSyncDot\");\n        const txt = document.getElementById(\"liveTimeText\");\n        pill.classList.remove(\"cached\", \"err\");\n        dot.classList.remove(\"busy\");\n        if (STORE.stateBusy || STORE.liveBusy) {\n          dot.classList.add(\"busy\");\n          txt.textContent = STORE.state ? \"后台同步中...\" : \"正在同步云端数据...\";\n          return;\n        }\n        if (STORE.stateErr && !STORE.state) {\n          pill.classList.add(\"err\");\n          txt.textContent = STORE.stateErr;\n          return;\n        }\n        if (STORE.stateSource === \"cache\" && STORE.liveSource === \"cache\") pill.classList.add(\"cached\");\n        const stamp = STORE.state?.meta?.updated_at_short || STORE.live?.updatedAtEt || STORE.live?.updatedAt || \"已同步\";\n        const sess = STORE.live ? sessionCn(STORE.live.marketSession) : \"\";\n        txt.textContent = `云端已同步 · ${stamp}${sess ? \" · \" + sess : \"\"}`;\n      }\n\n      /* Hero Brief */\n      function renderHero() {\n        const el = document.getElementById(\"heroContainer\");\n        if (!STORE.state) {\n          el.innerHTML = `<div class=\"empty-box\">${esc(STORE.stateErr || \"正在加载全市场主线研判...\")}</div>`;\n          return;\n        }\n        const meta = STORE.state.meta || {};\n        const qm = quoteMap();\n        const qVix = qm[\"^VIX\"], qTnx = qm[\"^TNX\"], qBtc = qm[\"BTC-USD\"];\n        const vixP = qVix ? numOrNull(qVix.price) : null;\n        const vixPct = vixP === null ? 40 : Math.max(12, Math.min(96, (vixP - 10) / 30 * 100));\n        const vixColor = vixP >= 25 ? \"var(--terra)\" : vixP >= 18 ? \"var(--ochre)\" : \"var(--sage)\";\n        const tnxP = qTnx ? numOrNull(qTnx.price) : null;\n        const tnxPct = tnxP === null ? 50 : Math.max(15, Math.min(95, (tnxP - 3) / 2.8 * 100));\n        const btcP = qBtc ? numOrNull(qBtc.price) : null;\n        const btcPct = btcP === null ? 50 : Math.max(15, Math.min(95, (btcP - 35000) / 85000 * 100));\n\n        const auditOpen = el.querySelector('[data-drawer=\"audit\"]')?.open;\n        const briefOpen = el.querySelector('[data-drawer=\"brief\"]')?.open;\n        const briefBlocks = String(meta.market_brief || \"\").trim().split(/\\n{2,}/).map(s => s.trim()).filter(Boolean);\n        const briefHtml = briefBlocks.map(b => `<p>${fmtHtml(b)}</p>`).join(\"\");\n\n        el.innerHTML = `\n          <div class=\"hero-top\">\n            <span class=\"pill tone-terra\">${fmtHtml(meta.badge || \"主线研判\")}</span>\n            <span class=\"hero-time\">${esc(meta.updated_at || meta.updated_at_short || \"\")}</span>\n          </div>\n          <h2 class=\"headline\">${fmtHtml(meta.headline || \"\")}</h2>\n          <div class=\"warm-box\"><strong>一句话看懂：</strong>${fmtHtml(meta.plain_guide || \"\")}</div>\n          <div class=\"grid-3\" style=\"margin-top:12px;\">\n            <div class=\"kpi-box\" data-kpi=\"^VIX\">\n              <div class=\"kpi-row\">\n                <span class=\"kpi-lbl\">VIX 恐慌指数</span>\n                <div style=\"display:flex;align-items:center;gap:6px;\">\n                  <span class=\"kpi-val\">${esc(qVix ? fmtPrice(\"^VIX\", qVix.price) : \"--\")}</span>\n                  <span class=\"kpi-chg ${qVix ? chgCls(qVix.chg) : \"chg-flat\"}\">${esc(qVix ? fmtChg(qVix.chg) : \"--\")}</span>\n                </div>\n              </div>\n              <div class=\"bar-bg\"><div class=\"bar-fill\" style=\"width:${vixPct.toFixed(1)}%;background:${vixColor};\"></div></div>\n              <div class=\"kpi-note\" title=\"${fmtHtml(meta.vix_note || \"\")}\">${fmtHtml(meta.vix_note || \"波动率监控\")}</div>\n            </div>\n            <div class=\"kpi-box\">\n              <div class=\"kpi-mini\" data-kpi=\"^TNX\">\n                <div class=\"kpi-row\">\n                  <span class=\"kpi-lbl\">10Y 美债</span>\n                  <div style=\"display:flex;align-items:center;gap:6px;\">\n                    <span class=\"kpi-val\" style=\"font-size:13.5px;\">${esc(qTnx ? fmtPrice(\"^TNX\", qTnx.price) : \"--\")}</span>\n                    <span class=\"kpi-chg ${qTnx ? chgCls(qTnx.chg) : \"chg-flat\"}\">${esc(qTnx ? fmtChg(qTnx.chg) : \"--\")}</span>\n                  </div>\n                </div>\n                <div class=\"bar-bg\" style=\"height:4px;margin-top:4px;\"><div class=\"bar-fill\" style=\"width:${tnxPct.toFixed(1)}%;background:var(--ochre);\"></div></div>\n              </div>\n              <div class=\"kpi-mini\" data-kpi=\"BTC-USD\">\n                <div class=\"kpi-row\">\n                  <span class=\"kpi-lbl\">比特币</span>\n                  <div style=\"display:flex;align-items:center;gap:6px;\">\n                    <span class=\"kpi-val\" style=\"font-size:13.5px;\">${esc(qBtc ? fmtPrice(\"BTC-USD\", qBtc.price) : \"--\")}</span>\n                    <span class=\"kpi-chg ${qBtc ? chgCls(qBtc.chg) : \"chg-flat\"}\">${esc(qBtc ? fmtChg(qBtc.chg) : \"--\")}</span>\n                  </div>\n                </div>\n                <div class=\"bar-bg\" style=\"height:4px;margin-top:4px;\"><div class=\"bar-fill\" style=\"width:${btcPct.toFixed(1)}%;background:var(--slate);\"></div></div>\n              </div>\n            </div>\n            <div class=\"blue-box\">\n              <span class=\"blue-lbl\">下一关键节点</span>\n              <div class=\"blue-txt\">${fmtHtml(meta.next_gate || \"等待下一交易窗口验证\")}</div>\n            </div>\n          </div>\n          <div class=\"drawer-row\">\n            ${meta.stance || meta.self_review ? `<details class=\"quiet\" data-drawer=\"audit\"${auditOpen ? \" open\" : \"\"}>\n              <summary>查看本轮六维自审与总控姿态</summary>\n              <div class=\"drawer-body\">\n                ${meta.regime ? `<p><strong>市场阶段：</strong>${fmtHtml(meta.regime)}</p>` : \"\"}\n                ${meta.stance ? `<p><strong>总控姿态：</strong>${fmtHtml(meta.stance)}</p>` : \"\"}\n                ${meta.self_review ? `<p><strong>六维自审：</strong>${fmtHtml(meta.self_review)}</p>` : \"\"}\n              </div>\n            </details>` : \"\"}\n            ${briefHtml ? `<details class=\"quiet\" data-drawer=\"brief\"${briefOpen ? \" open\" : \"\"}>\n              <summary>展开跨市场增量快报</summary>\n              <div class=\"drawer-body\">${briefHtml}</div>\n            </details>` : \"\"}\n          </div>\n        `;\n      }\n\n      function patchHeroKpis() {\n        const qm = quoteMap();\n        document.querySelectorAll(\"[data-kpi]\").forEach(node => {\n          const sym = node.getAttribute(\"data-kpi\");\n          const q = qm[sym];\n          const v = node.querySelector(\".kpi-val\");\n          const c = node.querySelector(\".kpi-chg\");\n          const bar = node.querySelector(\".bar-fill\");\n          if (v) v.textContent = q ? fmtPrice(sym, q.price) : \"--\";\n          if (c) { c.textContent = q ? fmtChg(q.chg) : \"--\"; c.className = \"kpi-chg \" + (q ? chgCls(q.chg) : \"chg-flat\"); }\n          if (bar && q && numOrNull(q.price) !== null) {\n            const p = q.price;\n            if (sym === \"^VIX\") {\n              bar.style.width = Math.max(12, Math.min(96, (p - 10) / 30 * 100)).toFixed(1) + \"%\";\n              bar.style.background = p >= 25 ? \"var(--terra)\" : p >= 18 ? \"var(--ochre)\" : \"var(--sage)\";\n            } else if (sym === \"^TNX\") {\n              bar.style.width = Math.max(15, Math.min(95, (p - 3) / 2.8 * 100)).toFixed(1) + \"%\";\n            } else if (sym === \"BTC-USD\") {\n              bar.style.width = Math.max(15, Math.min(95, (p - 35000) / 85000 * 100)).toFixed(1) + \"%\";\n            }\n          }\n        });\n      }\n\n      /* Ticker Strip */\n      function renderQuoteRibbon() {\n        const el = document.getElementById(\"quoteRibbon\");\n        const timeEl = document.getElementById(\"quoteRibbonTime\");\n        timeEl.textContent = STORE.live\n          ? `${sessionCn(STORE.live.marketSession)} · 实时行情已更新`\n          : (STORE.liveBusy ? \"同步中...\" : \"等待行情\");\n        const qm = quoteMap();\n        const syms = [...new Set([\n          \"NQ=F\", \"ES=F\", \"NVDA\", \"TSM\", \"AVGO\", \"ASML\", \"BTC-USD\", \"GC=F\", \"BZ=F\",\n          ...(STORE.state?.mainlines || []).map(m => m.anchor_sym), \"TLT\", \"XLE\", \"ITB\", \"LMT\"\n        ])].filter(s => qm[s] && numOrNull(qm[s].price) !== null).slice(0, 12);\n        if (!syms.length) {\n          el.innerHTML = `<div class=\"empty-box\" style=\"width:100%;\">${STORE.liveBusy ? \"正在同步实时行情...\" : \"暂无实时行情\"}</div>`;\n          return;\n        }\n        el.innerHTML = syms.map(sym => {\n          const q = qm[sym];\n          const isRaw = /[=^.-]/.test(sym);\n          const lbl = isRaw ? (ASSET_CN[sym] || q.name || sym) : sym;\n          const sub = !isRaw && ASSET_CN[sym] ? `<span class=\"muted\" style=\"font-size:11px;\">${esc(ASSET_CN[sym])}</span>` : \"\";\n          return `<div class=\"ticker-item\"><strong>${esc(lbl)}</strong>${sub}<span class=\"px\">${esc(fmtPrice(sym, q.price))}</span><span class=\"pct ${chgCls(q.chg)}\">${esc(fmtChg(q.chg))}</span></div>`;\n        }).join(\"\");\n      }\n\n      /* Mainlines & Momentum */\n      function renderMomentum() {\n        const el = document.getElementById(\"mainlineMomentum\");\n        const rows = [...(STORE.state?.mainlines || [])];\n        const pill = document.getElementById(\"clearMainlinePill\");\n        pill.textContent = STORE.mainlineFilter ? `已筛选 ${STORE.mainlineFilter} · 点此重置` : `全部 ${rows.length} 条主线`;\n        el.innerHTML = rows.length ? rows.map((m, i) => {\n          const s = Math.max(0, Math.min(100, Number(m.score) || 0));\n          const color = m.action_tone === \"terra\" ? \"var(--terra)\" : m.action_tone === \"ochre\" ? \"var(--ochre)\" : \"var(--sage)\";\n          return `<button type=\"button\" class=\"mom-row\" data-mainline-filter=\"${esc(m.id)}\" aria-pressed=\"${STORE.mainlineFilter === m.id}\">\n            <span class=\"mom-lbl\">${esc(m.id)} ${esc(m.title)}</span>\n            <span class=\"mom-track\"><span class=\"mom-fill\" style=\"width:${s}%;background:${color};display:block;\"></span></span>\n            <span class=\"mom-val\">${s}分</span>\n          </button>`;\n        }).join(\"\") : '<div class=\"empty-box\">暂无主线评分</div>';\n      }\n\n      function renderMainlines() {\n        const el = document.getElementById(\"mainlinesContainer\");\n        const rows = STORE.state?.mainlines || [];\n        if (!rows.length) { el.innerHTML = \"\"; return; }\n        const qm = quoteMap();\n\n        el.innerHTML = rows.map(m => {\n          const steps = String(m.chain || \"\").split(/\\s*(?:\\||->|→)\\s*/).map(s => s.trim()).filter(Boolean);\n          const timelineHtml = steps.map((st, idx) => `\n            <div class=\"chain-node${idx === 0 ? \" is-first\" : \"\"}\">\n              <span class=\"chain-step-tag\">0${idx + 1}</span>\n              <span>${fmtHtml(st)}</span>\n            </div>\n          `).join(\"\");\n\n          const pairs = parseStocks(m.stocks);\n          const tagsHtml = pairs.map(({ sym, name }) => {\n            const q = qm[sym];\n            const chg = q ? fmtChg(q.chg) : \"\";\n            const cls = q ? chgCls(q.chg) : \"chg-flat\";\n            const isRaw = /[=^.-]/.test(sym);\n            const showSym = isRaw ? (name || ASSET_CN[sym] || sym) : sym;\n            const showName = isRaw || showSym === name ? \"\" : `<span class=\"muted\">${esc(name)}</span>`;\n            return `<span class=\"stock-tag\" data-sym=\"${esc(sym)}\"><strong>${esc(showSym)}</strong>${showName}${chg ? `<span class=\"pct ${cls}\" style=\"background:none;padding:0;\">${esc(chg)}</span>` : \"\"}</span>`;\n          }).join(\"\");\n\n          const anchor = m.anchor_sym || \"\";\n          const qa = qm[anchor];\n          const curPx = qa ? fmtPrice(anchor, qa.price) : \"--\";\n          const anchorLabel = /[=^.-]/.test(anchor) ? (ASSET_CN[anchor] || anchor) : anchor;\n          const src = safeUrl(m.source_url);\n          const r = m.reasoning;\n          const cleanStatus = humanizeCopy(m.status || \"\");\n\n          const detailsParts = [];\n          if (m.summary) detailsParts.push(`<p><strong>研究拆解：</strong>${fmtHtml(m.summary)}</p>`);\n          if (r) {\n            const rFields = [[\"传导假设\", r.hypothesis], [\"确认条件\", r.confirmation], [\"失效条件\", r.invalidation], [\"证据缺口\", r.uncertainty]];\n            for (const [k, v] of rFields) if (v) detailsParts.push(`<p><strong>${k}：</strong>${fmtHtml(v)}</p>`);\n            if (Array.isArray(r.evidence) && r.evidence.length) {\n              detailsParts.push(`<ul>${r.evidence.map(it => {\n                const u = safeUrl(it.source_url);\n                const lbl = esc([it.source, it.as_of].filter(Boolean).join(\" · \"));\n                return `<li>${fmtHtml(it.text)} ${u ? `<a class=\"src-link\" href=\"${esc(u)}\" target=\"_blank\" rel=\"noopener noreferrer\">${lbl} ↗</a>` : lbl}</li>`;\n              }).join(\"\")}</ul>`);\n            }\n          }\n\n          return `\n            <article class=\"m-card${STORE.mainlineFilter === m.id ? \" selected\" : \"\"}\" data-mainline-id=\"${esc(m.id)}\">\n              <div class=\"m-head\">\n                <div>\n                  <button type=\"button\" class=\"m-title\" data-mainline-filter=\"${esc(m.id)}\">${esc(m.id)} · ${fmtHtml(m.title)}</button>\n                  <div class=\"m-meta\">热度 ${esc(m.score)} 分 · 首次发现 ${esc(m.first_seen)}${cleanStatus ? \" · \" + esc(cleanStatus) : \"\"}</div>\n                </div>\n                <span class=\"pill ${toneCls(m.action_tone)}\">${fmtHtml(m.action)}</span>\n              </div>\n              <div class=\"chain-timeline\">${timelineHtml}</div>\n              <div class=\"stock-row\">\n                <div class=\"stock-tags\">${tagsHtml}</div>\n                <div class=\"m-anchor\" data-anchor=\"${esc(anchor)}\">\n                  <span>锚点 <strong>${esc(anchorLabel)}</strong> <span class=\"anchor-px\">${esc(curPx)}</span></span>\n                  <span>确认 ${esc(fmtLvl(m.accel))} · 防守 ${esc(fmtLvl(m.flip))}</span>\n                </div>\n              </div>\n              <div class=\"warm-box\">${fmtHtml(m.plain || \"\")}</div>\n              <div class=\"m-watch\">\n                <div><strong>盯盘节点：</strong>${fmtHtml(m.watch_points || \"\")}</div>\n                ${src ? `<a class=\"src-link\" href=\"${esc(src)}\" target=\"_blank\" rel=\"noopener noreferrer\">一手源 ↗</a>` : \"\"}\n              </div>\n              ${detailsParts.length ? `<details class=\"quiet m-more\"><summary>展开研究拆解与证据验证</summary><div class=\"drawer-body\">${detailsParts.join(\"\")}</div></details>` : \"\"}\n            </article>\n          `;\n        }).join(\"\");\n      }\n\n      function patchMainlinesLive() {\n        const qm = quoteMap();\n        document.querySelectorAll(\".stock-tag[data-sym]\").forEach(tag => {\n          const q = qm[tag.getAttribute(\"data-sym\")];\n          const pct = tag.querySelector(\".pct\");\n          if (q && pct) { pct.textContent = fmtChg(q.chg); pct.className = \"pct \" + chgCls(q.chg); }\n        });\n        document.querySelectorAll(\".m-anchor[data-anchor]\").forEach(el => {\n          const sym = el.getAttribute(\"data-anchor\");\n          const px = el.querySelector(\".anchor-px\");\n          if (px && qm[sym]) px.textContent = fmtPrice(sym, qm[sym].price);\n        });\n      }\n\n      /* SVG Chart Helpers */\n      function renderSvgLineChart(containerId, labels, allSeries, legendId, unit = \"\", baseline = null, bucketKey = \"overview\") {\n        const box = document.getElementById(containerId);\n        const leg = document.getElementById(legendId);\n        if (!box) return;\n        const hidden = STORE.hiddenSeries[bucketKey];\n        const series = allSeries.filter(s => !hidden.has(s.label));\n        const vals = series.flatMap(s => s.values).map(numOrNull).filter(v => v !== null);\n        if (baseline !== null && vals.length) vals.push(baseline);\n        if (!vals.length) {\n          box.innerHTML = '<div class=\"empty-box\">暂无曲线数据</div>';\n          if (leg) leg.innerHTML = \"\";\n          return;\n        }\n        const W = 760, H = 220, L = 46, R = 18, T = 16, B = 28;\n        const minV = Math.min(...vals), maxV = Math.max(...vals);\n        const pad = minV === maxV ? 1 : (maxV - minV) * 0.12;\n        const y0 = minV - pad, y1 = maxV + pad;\n        const steps = Math.max(2, labels.length, ...series.map(s => s.values.length));\n        const gx = i => L + i * (W - L - R) / (steps - 1);\n        const gy = v => T + (y1 - v) * (H - T - B) / (y1 - y0);\n\n        let grid = \"\";\n        for (let k = 0; k <= 4; k++) {\n          const val = y0 + (y1 - y0) * k / 4;\n          const y = gy(val);\n          grid += `<line x1=\"${L}\" y1=\"${y.toFixed(1)}\" x2=\"${W - R}\" y2=\"${y.toFixed(1)}\" stroke=\"#E6E1D6\" stroke-width=\"1\"/>`;\n          grid += `<text x=\"${L - 6}\" y=\"${(y + 4).toFixed(1)}\" text-anchor=\"end\" fill=\"#666F69\" font-size=\"10.5\" font-family=\"var(--mono)\">${val.toFixed(unit ? 1 : 0)}${unit}</text>`;\n        }\n        if (baseline !== null && baseline >= y0 && baseline <= y1) {\n          const by = gy(baseline);\n          grid += `<line x1=\"${L}\" y1=\"${by.toFixed(1)}\" x2=\"${W - R}\" y2=\"${by.toFixed(1)}\" stroke=\"#9BA49E\" stroke-dasharray=\"4 4\"/>`;\n        }\n        const xTicks = [0, Math.floor((labels.length - 1) / 2), labels.length - 1].filter(i => i >= 0 && labels[i]);\n        const xLabels = [...new Set(xTicks)].map(i => `<text x=\"${gx(i).toFixed(1)}\" y=\"${H - 6}\" text-anchor=\"middle\" fill=\"#666F69\" font-size=\"10.5\" font-family=\"var(--mono)\">${esc(String(labels[i]).slice(-5))}</text>`).join(\"\");\n\n        const paths = series.map(s => {\n          const pts = s.values.map((v, i) => numOrNull(v) !== null ? `${gx(i).toFixed(1)},${gy(v).toFixed(1)}` : null).filter(Boolean);\n          const lastV = [...s.values].reverse().find(v => numOrNull(v) !== null);\n          const lastIdx = s.values.length - 1;\n          return `<polyline fill=\"none\" stroke=\"${s.color}\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" points=\"${pts.join(\" \")}\"/>`\n            + (numOrNull(lastV) !== null ? `<circle cx=\"${gx(lastIdx).toFixed(1)}\" cy=\"${gy(lastV).toFixed(1)}\" r=\"3.5\" fill=\"${s.color}\" stroke=\"#fff\" stroke-width=\"1.5\"/>` : \"\");\n        }).join(\"\");\n\n        box.innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"趋势折线图\">${grid}${xLabels}${paths}</svg>`;\n        if (leg) {\n          leg.innerHTML = allSeries.map((s, i) => `\n            <button type=\"button\" class=\"legend-btn\" data-leg=\"${bucketKey}:${i}\" aria-pressed=\"${!hidden.has(s.label)}\">\n              <span class=\"legend-dot\" style=\"background:${s.color};\"></span>${esc(s.label)}\n            </button>\n          `).join(\"\");\n          leg.onclick = ev => {\n            const btn = ev.target.closest(\"[data-leg]\");\n            if (!btn) return;\n            const idx = Number(btn.dataset.leg.split(\":\")[1]);\n            const lbl = allSeries[idx]?.label;\n            if (!lbl) return;\n            if (hidden.has(lbl)) hidden.delete(lbl);\n            else if (series.length > 1) hidden.add(lbl);\n            renderSvgLineChart(containerId, labels, allSeries, legendId, unit, baseline, bucketKey);\n          };\n        }\n      }\n\n      /* Setup Valuation × Drawdown Radar */\n      const SETUP_TONE = { dip: [\"ochre\", \"#B87D2B\"], hedge: [\"sage\", \"#2E6F5E\"], spec: [\"slate\", \"#47627A\"], avoid: [\"terra\", \"#B84A39\"], watch: [\"slate\", \"#666F69\"] };\n\n      function renderSetupRadar() {\n        const allRows = Array.isArray(STORE.state?.setups) ? STORE.state.setups : [];\n        const ml = (STORE.state?.mainlines || []).find(r => r.id === STORE.mainlineFilter);\n        const byMl = STORE.mainlineFilter ? allRows.filter(r => r.mainline === STORE.mainlineFilter) : allRows;\n        const visible = STORE.setupCategory === \"all\" ? byMl : byMl.filter(r => r.category === STORE.setupCategory);\n\n        document.querySelectorAll(\"[data-setup-category]\").forEach(b => {\n          b.classList.toggle(\"active\", b.dataset.setupCategory === STORE.setupCategory);\n        });\n        document.getElementById(\"setupCoverage\").textContent = allRows.length\n          ? `${ml ? ml.id + \" \" + ml.title : \"全部主线\"} · ${visible.length} 个观察标的 · 按距 52 周高点回撤深度与远期 PE 分布`\n          : \"等待估值与回撤数据同步\";\n\n        const pts = visible.flatMap((row, idx) => {\n          const dd = numOrNull(row.drawdown_52w_pct);\n          const pe = numOrNull(row.valuation?.forward_pe);\n          if (dd === null || pe === null || pe <= 0) return [];\n          return [{ idx, sym: row.symbol, x: Math.abs(dd), y: pe, color: (SETUP_TONE[row.category] || SETUP_TONE.watch)[1] }];\n        });\n\n        const plotEl = document.getElementById(\"setupPlot\");\n        if (pts.length) {\n          const W = 760, H = 235, L = 54, R = 36, T = 20, B = 34;\n          const xMax = Math.max(40, ...pts.map(p => p.x)) * 1.12;\n          const yMax = Math.max(35, ...pts.map(p => p.y)) * 1.15;\n          const gx = x => L + (x / xMax) * (W - L - R);\n          const gy = y => H - B - (y / yMax) * (H - T - B);\n          const mx = gx(xMax * 0.45), my = gy(yMax * 0.5);\n\n          const quads = `\n            <rect x=\"${L}\" y=\"${T}\" width=\"${mx - L}\" height=\"${my - T}\" fill=\"#EEF2EE\" opacity=\".75\"/>\n            <rect x=\"${mx}\" y=\"${T}\" width=\"${W - R - mx}\" height=\"${my - T}\" fill=\"#FBF5E8\" opacity=\".8\"/>\n            <rect x=\"${L}\" y=\"${my}\" width=\"${mx - L}\" height=\"${H - B - my}\" fill=\"#EAEFEA\" opacity=\".75\"/>\n            <rect x=\"${mx}\" y=\"${my}\" width=\"${W - R - mx}\" height=\"${H - B - my}\" fill=\"#E6EFEA\" opacity=\".95\"/>\n            <line x1=\"${mx}\" y1=\"${T}\" x2=\"${mx}\" y2=\"${H - B}\" stroke=\"#C9C4B8\" stroke-dasharray=\"4 4\"/>\n            <line x1=\"${L}\" y1=\"${my}\" x2=\"${W - R}\" y2=\"${my}\" stroke=\"#C9C4B8\" stroke-dasharray=\"4 4\"/>\n            <text x=\"${L + 10}\" y=\"${T + 16}\" fill=\"#47627A\" font-size=\"11\" font-weight=\"700\">低波高估值观察</text>\n            <text x=\"${mx + 10}\" y=\"${T + 16}\" fill=\"#B87D2B\" font-size=\"11\" font-weight=\"700\">深跌高波博弈</text>\n            <text x=\"${L + 10}\" y=\"${H - B - 10}\" fill=\"#2E6F5E\" font-size=\"11\" font-weight=\"700\">低波防御估值底</text>\n            <text x=\"${mx + 10}\" y=\"${H - B - 10}\" fill=\"#2E6F5E\" font-size=\"11\" font-weight=\"700\">★ 深跌 + 低 PE 安全垫区</text>\n            <text x=\"${(L + W - R) / 2}\" y=\"${H - 8}\" text-anchor=\"middle\" fill=\"#666F69\" font-size=\"11\">距 52 周高点回撤深度 (%) → 越右跌越深</text>\n            <text x=\"16\" y=\"${(T + H - B) / 2}\" text-anchor=\"middle\" transform=\"rotate(-90 16 ${(T + H - B) / 2})\" fill=\"#666F69\" font-size=\"11\">远期市盈率 (倍)</text>\n          `;\n          const placed = [];\n          const dots = pts.map(p => {\n            const cx = gx(p.x), cy = gy(p.y);\n            let ly = cy + 4;\n            for (const off of [4, -12, 18, -24]) {\n              if (!placed.some(q => Math.abs(q.x - (cx + 10)) < 46 && Math.abs(q.y - (cy + off)) < 14)) { ly = cy + off; break; }\n            }\n            placed.push({ x: cx + 10, y: ly });\n            return `<g class=\"svg-dot\" data-setup-focus=\"${p.idx}\" style=\"cursor:pointer;\">\n              <circle cx=\"${cx.toFixed(1)}\" cy=\"${cy.toFixed(1)}\" r=\"7.5\" fill=\"${p.color}\" stroke=\"#FFF\" stroke-width=\"2\"/>\n              <text x=\"${(cx + 11).toFixed(1)}\" y=\"${ly.toFixed(1)}\" fill=\"#1E2320\" font-size=\"11.5\" font-weight=\"700\" font-family=\"var(--mono)\">${esc(p.sym)}</text>\n            </g>`;\n          }).join(\"\");\n          plotEl.innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"回撤深度与远期市盈率四象限图\">${quads}${dots}</svg>`;\n        } else {\n          plotEl.innerHTML = '<div class=\"empty-box\">具备正远期市盈率与 52 周回撤数据的标的将显示于此，下方卡片展示全部观察锚。</div>';\n        }\n\n        const cardsEl = document.getElementById(\"setupCards\");\n        cardsEl.innerHTML = visible.length ? visible.map((row, idx) => {\n          const v = row.valuation || {};\n          const dd = numOrNull(row.drawdown_52w_pct);\n          const pe = numOrNull(v.forward_pe);\n          const disc = numOrNull(v.forward_pe_discount_pct);\n          const rr = numOrNull(row.reward_risk);\n          const lp = numOrNull(row.last_price);\n          const inv = numOrNull(row.invalidation_price);\n          const tgt = numOrNull(row.target_price);\n          const tone = (SETUP_TONE[row.category] || SETUP_TONE.watch)[0];\n          const valParts = [];\n          if (pe !== null) valParts.push(`远期 PE ${pe.toFixed(1)}x`);\n          if (disc !== null) valParts.push(disc > 0 ? `较历史折价 ${disc.toFixed(0)}%` : `较历史溢价 ${Math.abs(disc).toFixed(0)}%`);\n          const valLine = valParts.length ? valParts.join(\" · \") : \"价格与区间观察锚\";\n\n          let pinPct = 50;\n          if (lp !== null && inv !== null && tgt !== null && tgt > inv) {\n            pinPct = Math.max(5, Math.min(95, (lp - inv) / (tgt - inv) * 100));\n          }\n          const src = safeUrl(row.source_url);\n          return `\n            <article class=\"setup-card\" tabindex=\"-1\" data-setup-idx=\"${idx}\">\n              <div class=\"setup-top\">\n                <div>\n                  <div style=\"display:flex;align-items:center;gap:6px;flex-wrap:wrap;\">\n                    <span class=\"setup-sym\">${esc(row.symbol)}</span>\n                    <span class=\"muted\" style=\"font-size:12px;\">${esc(row.name || \"\")}</span>\n                    <span class=\"mini-tag\">${esc(row.mainline)}</span>\n                  </div>\n                  <div class=\"setup-val-line\">${esc(valLine)}</div>\n                </div>\n                <span class=\"pill tone-${tone}\">${esc(row.category_label || \"待观察\")}</span>\n              </div>\n              <div class=\"setup-nums\">\n                <div><span>现价锚</span><strong>${esc(lp !== null ? fmtPrice(row.symbol, lp) : \"--\")}</strong></div>\n                <div><span>距52W高点</span><strong style=\"color:var(--terra);\">${dd !== null ? \"-\" + Math.abs(dd).toFixed(1) + \"%\" : \"--\"}</strong></div>\n                <div><span>盈亏比</span><strong style=\"color:var(--sage);\">${rr !== null ? rr.toFixed(1) + \" : 1\" : \"--\"}</strong></div>\n              </div>\n              <div>\n                <div class=\"ladder-labels\">\n                  <span style=\"color:var(--terra);\">防守 ${esc(inv !== null ? fmtPrice(row.symbol, inv) : \"--\")}</span>\n                  <span style=\"color:var(--ink);font-weight:700;\">现价 ${esc(lp !== null ? fmtPrice(row.symbol, lp) : \"--\")}</span>\n                  <span style=\"color:var(--sage);\">目标 ${esc(tgt !== null ? fmtPrice(row.symbol, tgt) : \"--\")}</span>\n                </div>\n                <div class=\"ladder-track\"><div class=\"ladder-pin\" style=\"left:${pinPct.toFixed(1)}%;\"></div></div>\n              </div>\n              <div class=\"setup-foot\">\n                ${fmtHtml(row.summary || \"\")}\n                ${src ? ` <a class=\"src-link\" href=\"${esc(src)}\" target=\"_blank\" rel=\"noopener noreferrer\">行情 ↗</a>` : \"\"}\n              </div>\n            </article>\n          `;\n        }).join(\"\") : '<div class=\"empty-box\" style=\"grid-column:1/-1;\">当前筛选下暂无观察标的</div>';\n      }\n\n      /* Tab 2: Candidates */\n      function visibleCandidates() {\n        const ord = { upgrade: 0, watch: 1, demote: 2 };\n        return (STORE.state?.candidates || [])\n          .filter(c => STORE.candFilter === \"all\" || c.tier === STORE.candFilter)\n          .sort((a, b) => (ord[a.tier] ?? 3) - (ord[b.tier] ?? 3));\n      }\n\n      function renderCandidateCharts() {\n        const rows = visibleCandidates();\n        const quadEl = document.getElementById(\"candQuadSvg\");\n        const barEl = document.getElementById(\"candBarSvg\");\n        const tierColor = { upgrade: \"#2E6F5E\", watch: \"#B87D2B\", demote: \"#47627A\" };\n        const pts = rows.map(c => ({ id: c.id, name: c.name, x: numOrNull(c.r20), y: numOrNull(c.r5), color: tierColor[c.tier] || \"#666F69\" }))\n          .filter(p => p.x !== null && p.y !== null);\n\n        if (pts.length) {\n          const W = 440, H = 220, P = 30;\n          const xMax = Math.max(8, ...pts.map(p => Math.abs(p.x))) * 1.25;\n          const yMax = Math.max(4, ...pts.map(p => Math.abs(p.y))) * 1.25;\n          const gx = v => P + (v + xMax) / (2 * xMax) * (W - 2 * P);\n          const gy = v => H - P - (v + yMax) / (2 * yMax) * (H - 2 * P);\n          const axes = `\n            <line x1=\"${P}\" y1=\"${gy(0).toFixed(1)}\" x2=\"${W - P}\" y2=\"${gy(0).toFixed(1)}\" stroke=\"#D6D1C6\" stroke-dasharray=\"4 4\"/>\n            <line x1=\"${gx(0).toFixed(1)}\" y1=\"${P - 10}\" x2=\"${gx(0).toFixed(1)}\" y2=\"${H - P}\" stroke=\"#D6D1C6\" stroke-dasharray=\"4 4\"/>\n            <text x=\"${W / 2}\" y=\"${H - 6}\" text-anchor=\"middle\" fill=\"#666F69\" font-size=\"10.5\">20日涨跌幅 (%)</text>\n          `;\n          const placed = [];\n          const dots = pts.map(p => {\n            const cx = gx(p.x), cy = gy(p.y);\n            const cands = [\n              [cx + 10, cy + 4], [cx + 10, cy + 16], [cx + 10, cy - 9],\n              [cx - 26, cy + 4], [cx - 26, cy + 16], [cx - 26, cy - 9],\n            ];\n            let [lx, ly] = cands[0];\n            for (const [tx, ty] of cands) {\n              const inBox = tx >= 8 && tx <= W - 26 && ty >= 14 && ty <= H - 18;\n              const hitPt = pts.some(o => Math.hypot(gx(o.x) - (tx + 8), gy(o.y) - (ty - 4)) < 14);\n              const hitLbl = placed.some(q => Math.abs(q.x - tx) < 26 && Math.abs(q.y - ty) < 13);\n              if (inBox && !hitPt && !hitLbl) { lx = tx; ly = ty; break; }\n            }\n            placed.push({ x: lx, y: ly });\n            return `<g data-cand-focus=\"${esc(p.id)}\" style=\"cursor:pointer;\">\n              <circle cx=\"${cx.toFixed(1)}\" cy=\"${cy.toFixed(1)}\" r=\"7\" fill=\"${p.color}\" stroke=\"#FFF\" stroke-width=\"2\"/>\n              <text x=\"${lx.toFixed(1)}\" y=\"${ly.toFixed(1)}\" fill=\"#1E2320\" font-size=\"11.5\" font-weight=\"700\" font-family=\"var(--mono)\">${esc(p.id)}</text>\n            </g>`;\n          }).join(\"\");\n          quadEl.innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\">${axes}${dots}</svg>`;\n        } else {\n          quadEl.innerHTML = '<div class=\"empty-box\">暂无象限数据</div>';\n        }\n\n        if (rows.length) {\n          const W = 440, H = 220, T = 18, B = 28, L = 18, R = 18;\n          const maxV = Math.max(5, ...rows.flatMap(r => [Math.abs(r.r5 || 0), Math.abs(r.r20 || 0)])) * 1.15;\n          const zeroY = T + (H - T - B) * 0.5;\n          const scale = (H - T - B) * 0.48 / maxV;\n          const up = cssVar(\"--up\") || \"#C43E32\";\n          const dn = cssVar(\"--down\") || \"#2E6F5E\";\n          const slot = (W - L - R) / rows.length;\n          const bw = Math.min(18, slot * 0.28);\n\n          const bars = rows.map((r, i) => {\n            const cx = L + slot * (i + 0.5);\n            const drawBar = (val, dx, op) => {\n              const n = numOrNull(val) ?? 0;\n              const h = Math.max(2, Math.abs(n) * scale);\n              const y = n >= 0 ? zeroY - h : zeroY;\n              return `<rect x=\"${(cx + dx).toFixed(1)}\" y=\"${y.toFixed(1)}\" width=\"${bw.toFixed(1)}\" height=\"${h.toFixed(1)}\" rx=\"3\" fill=\"${n >= 0 ? up : dn}\" opacity=\"${op}\"/>`;\n            };\n            return drawBar(r.r5, -bw - 2, \"1\") + drawBar(r.r20, 2, \"0.45\")\n              + `<text x=\"${cx.toFixed(1)}\" y=\"${H - 8}\" text-anchor=\"middle\" fill=\"#1E2320\" font-size=\"11.5\" font-weight=\"700\" font-family=\"var(--mono)\">${esc(r.id)}</text>`;\n          }).join(\"\");\n          barEl.innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\"><line x1=\"${L}\" y1=\"${zeroY.toFixed(1)}\" x2=\"${W - R}\" y2=\"${zeroY.toFixed(1)}\" stroke=\"#D6D1C6\"/>${bars}</svg>`;\n        } else {\n          barEl.innerHTML = '<div class=\"empty-box\">暂无对比数据</div>';\n        }\n      }\n\n      function renderCandidates() {\n        const all = STORE.state?.candidates || [];\n        const cnt = {\n          all: all.length,\n          upgrade: all.filter(c => c.tier === \"upgrade\").length,\n          watch: all.filter(c => c.tier === \"watch\").length,\n          demote: all.filter(c => c.tier === \"demote\").length,\n        };\n        const lbls = { all: `全部 (${cnt.all})`, upgrade: `↑ 准备升级 (${cnt.upgrade})`, watch: `● 强化跟踪 (${cnt.watch})`, demote: `↓ 弱化/淘汰 (${cnt.demote})` };\n        document.querySelectorAll(\"[data-cfilter]\").forEach(b => {\n          const k = b.dataset.cfilter;\n          b.textContent = lbls[k] || \"\";\n          b.classList.toggle(\"active\", k === STORE.candFilter);\n        });\n\n        const rows = visibleCandidates();\n        const el = document.getElementById(\"candidatesContainer\");\n        el.innerHTML = rows.length ? rows.map(c => {\n          const stocksLabel = parseStocks(c.stocks).map(p => `${p.name}(${p.sym})`).join(\"、\");\n          return `\n            <article class=\"cand-card\" data-cand-id=\"${esc(c.id)}\">\n              <div class=\"kpi-row\">\n                <div style=\"display:flex;align-items:center;gap:6px;\">\n                  <span class=\"mini-tag\">${esc(c.id)}</span>\n                  <span class=\"pill ${toneCls(c.tone)}\">${esc(c.tier_label)}</span>\n                </div>\n                <span class=\"faint\" style=\"font-size:11px;\">入池 ${esc(c.first_seen)}</span>\n              </div>\n              <div style=\"display:flex;gap:6px;flex-wrap:wrap;\">\n                <span class=\"pill ${chgCls(c.r5)}\">5日 ${esc(fmtChg(c.r5))}</span>\n                <span class=\"pill ${chgCls(c.r20)}\">20日 ${esc(fmtChg(c.r20))}</span>\n              </div>\n              <h3 class=\"cand-title\">${fmtHtml(c.name)}</h3>\n              <div class=\"muted\" style=\"font-size:11.5px;\">挂钩：${esc(c.linked_to)} · ${esc(stocksLabel || \"--\")}</div>\n              <div style=\"font-size:12.5px;color:#2C322F;\"><strong>白话解读：</strong>${fmtHtml(c.plain)}</div>\n              <div class=\"cand-rule\"><strong>考核规则：</strong>${fmtHtml(c.rule)}</div>\n            </article>\n          `;\n        }).join(\"\") : '<div class=\"empty-box\" style=\"grid-column:1/-1;\">当前筛选下暂无候补方向</div>';\n        renderCandidateCharts();\n      }\n\n      /* Tab 3: Cross-Asset Linkage */\n      function renderLinkage() {\n        const an = STORE.state?.analytics || {};\n        const rawLabels = an.corrLabels || [];\n        const mat = an.corrMatrix || [];\n        const up = cssVar(\"--up\") || \"#C43E32\";\n        const dn = cssVar(\"--down\") || \"#2E6F5E\";\n        const greenUp = document.body.classList.contains(\"green-up\");\n        const upRgba = a => greenUp ? `rgba(46,111,94,${a})` : `rgba(196,62,50,${a})`;\n        const dnRgba = a => greenUp ? `rgba(196,62,50,${a})` : `rgba(46,111,94,${a})`;\n\n        const mWrap = document.getElementById(\"corrMatrixWrap\");\n        if (rawLabels.length && mat.length) {\n          const disp = rawLabels.map(l => ASSET_CN[l] || l);\n          const head = `<tr><th></th>${disp.map(d => `<th>${esc(d)}</th>`).join(\"\")}</tr>`;\n          const body = disp.map((rowLbl, i) => {\n            const cells = disp.map((_, j) => {\n              if (i === j) return `<td style=\"background:#EAE6DC;color:#87908A;\">—</td>`;\n              const v = numOrNull(mat[i]?.[j]);\n              if (v === null) return `<td style=\"background:var(--sub);\">--</td>`;\n              const a = (0.09 + Math.min(1, Math.abs(v)) * 0.25).toFixed(2);\n              const bg = v > 0 ? upRgba(a) : v < 0 ? dnRgba(a) : \"#FAF8F4\";\n              const fg = v > 0 ? up : v < 0 ? dn : \"#666F69\";\n              return `<td style=\"background:${bg};color:${fg};\">${v > 0 ? \"+\" : \"\"}${v.toFixed(2)}</td>`;\n            }).join(\"\");\n            return `<tr><th style=\"text-align:left;padding-right:8px;\">${esc(rowLbl)}</th>${cells}</tr>`;\n          }).join(\"\");\n          mWrap.innerHTML = `<table class=\"matrix\"><thead>${head}</thead><tbody>${body}</tbody></table>`;\n        } else {\n          mWrap.innerHTML = '<div class=\"empty-box\">暂无相关性矩阵数据</div>';\n        }\n\n        const stories = STORE.state?.linkage || [];\n        const barEl = document.getElementById(\"linkageBarSvg\");\n        if (stories.length) {\n          const W = 740, rowH = 38, H = stories.length * rowH + 16, lblRight = 185, mid = 465, maxBar = 205;\n          const rowsSvg = stories.map((it, i) => {\n            const cStr = String(it.corr || \"\");\n            const m = cStr.match(/[+-]\\d+\\.\\d+/) || cStr.match(/相关[^\\d+-]*([+-]?\\d+(?:\\.\\d+)?)/);\n            const rawVal = m ? parseFloat(m[1] ?? m[0]) : 0;\n            const val = Number.isFinite(rawVal) ? Math.max(-1, Math.min(1, rawVal)) : 0;\n            const y = 12 + i * rowH;\n            const w = Math.max(4, Math.abs(val) * maxBar);\n            const x = val >= 0 ? mid : mid - w;\n            const col = val >= 0 ? up : dn;\n            const lblX = val >= 0 ? x + w + 8 : x - 8;\n            const anc = val >= 0 ? \"start\" : \"end\";\n            const shortPair = humanizeCopy(it.pair).replace(/\\s*[（(][^）)]*[）)]/g, \"\").slice(0, 14);\n            return `\n              <text x=\"${lblRight}\" y=\"${y + 18}\" text-anchor=\"end\" fill=\"#1E2320\" font-size=\"12\" font-weight=\"700\">${esc(shortPair)}</text>\n              <rect x=\"${x.toFixed(1)}\" y=\"${y + 5}\" width=\"${w.toFixed(1)}\" height=\"18\" rx=\"6\" fill=\"${col}\"/>\n              <text x=\"${lblX.toFixed(1)}\" y=\"${y + 18}\" text-anchor=\"${anc}\" fill=\"${col}\" font-size=\"12\" font-weight=\"700\" font-family=\"var(--mono)\">${val > 0 ? \"+\" : \"\"}${val.toFixed(2)}</text>\n            `;\n          }).join(\"\");\n          barEl.innerHTML = `<svg viewBox=\"0 0 ${W} ${H}\"><line x1=\"${mid}\" y1=\"6\" x2=\"${mid}\" y2=\"${H - 6}\" stroke=\"#D6D1C6\" stroke-width=\"1.5\"/>${rowsSvg}</svg>`;\n        } else {\n          barEl.innerHTML = '<div class=\"empty-box\">暂无联动读数</div>';\n        }\n\n        document.getElementById(\"linkageStoriesContainer\").innerHTML = stories.map(it => `\n          <article class=\"link-card\">\n            <div class=\"kpi-row\" style=\"flex-wrap:wrap;\">\n              <strong style=\"font-size:14px;\">${fmtHtml(it.pair)}</strong>\n              <span class=\"pill ${toneCls(it.tone)}\">${fmtHtml(it.corr)}</span>\n            </div>\n            <div style=\"font-size:12.5px;color:#2C322F;\">${fmtHtml(it.why)}</div>\n            <div class=\"link-signal\"><strong>交易信号：</strong>${fmtHtml(it.signal)}</div>\n          </article>\n        `).join(\"\");\n\n        const lt = an.linkageTrend;\n        if (lt?.series?.length) {\n          renderSvgLineChart(\"linkageTrendSvg\", lt.labels || [], lt.series.map((s, i) => ({\n            label: humanizeCopy(s.label || s.sym), values: s.values || [], color: PALETTE[i % PALETTE.length],\n          })), \"linkageTrendLegend\", \"%\", 0, \"linkage\");\n        }\n      }\n\n      /* Tab 4: Macro, Radar & Calendar */\n      const RADAR_AXES = [\n        [\"rate\", \"利率与债市\"], [\"credit\", \"信用与利差\"], [\"sentiment\", \"恐慌与风偏\"],\n        [\"compute\", \"电力与云基建\"], [\"semi_demand\", \"半导体动量\"],\n      ];\n\n      function renderMacro() {\n        const macro = STORE.state?.macro || [];\n        const rows = RADAR_AXES.map(([id, label]) => {\n          const m = macro.find(x => x.chain_id === id);\n          const s = m && Number.isFinite(Number(m.score)) ? Number(m.score) : 50;\n          return { id, label, m, score: Math.max(0, Math.min(100, s)) };\n        });\n\n        const headwinds = rows.filter(r => r.m?.wind === \"逆风\").length;\n        const tailwinds = rows.filter(r => r.m?.wind === \"顺风\").length;\n        document.getElementById(\"radarRegime\").textContent =\n          headwinds >= 4 ? \"普遍承压\" : tailwinds >= 4 ? \"整体偏顺风\" : \"顺逆风交织\";\n\n        const S = 320, cx = S / 2, cy = S / 2, R = 104;\n        const pt = (i, v) => {\n          const a = i * Math.PI * 2 / 5 - Math.PI / 2;\n          return [cx + Math.cos(a) * R * v / 100, cy + Math.sin(a) * R * v / 100];\n        };\n        const rings = [25, 50, 75, 100].map(r => `<polygon fill=\"none\" stroke=\"#E0DAD0\" points=\"${rows.map((_, i) => pt(i, r).map(n => n.toFixed(1)).join(\",\")).join(\" \")}\"/>`).join(\"\");\n        const spokes = rows.map((_, i) => {\n          const [x, y] = pt(i, 100);\n          return `<line x1=\"${cx}\" y1=\"${cy}\" x2=\"${x.toFixed(1)}\" y2=\"${y.toFixed(1)}\" stroke=\"#E0DAD0\"/>`;\n        }).join(\"\");\n        const poly = `<polygon fill=\"rgba(46,111,94,.18)\" stroke=\"#2E6F5E\" stroke-width=\"2\" points=\"${rows.map((r, i) => pt(i, r.score).map(n => n.toFixed(1)).join(\",\")).join(\" \")}\"/>`;\n        const dotsAndLbls = rows.map((r, i) => {\n          const [x, y] = pt(i, r.score);\n          const [lx, ly] = pt(i, 124);\n          const col = r.score >= 60 ? \"#2E6F5E\" : r.score >= 45 ? \"#B87D2B\" : \"#B84A39\";\n          return `<circle cx=\"${x.toFixed(1)}\" cy=\"${y.toFixed(1)}\" r=\"4.5\" fill=\"${col}\" stroke=\"#FFF\" stroke-width=\"1.5\"/>\n            <text x=\"${lx.toFixed(1)}\" y=\"${(ly + 4).toFixed(1)}\" text-anchor=\"middle\" fill=\"#1E2320\" font-size=\"11.5\" font-weight=\"700\">${esc(r.label)}</text>`;\n        }).join(\"\");\n\n        document.getElementById(\"macroRadarSvg\").innerHTML = `<svg viewBox=\"0 0 ${S} ${S}\" style=\"max-width:340px;margin:0 auto;\">${rings}${spokes}${poly}${dotsAndLbls}</svg>`;\n        document.getElementById(\"radarDimensions\").innerHTML = rows.map(r =>\n          `<button type=\"button\" class=\"f-btn\" data-macro-jump=\"${esc(r.id)}\">${esc(r.label)} · ${r.score}</button>`\n        ).join(\"\");\n        document.getElementById(\"radarComparison\").textContent = `研究快照：${STORE.state?.serverSyncedAt || \"等待同步\"} · 评分为规则代理观察值`;\n\n        document.getElementById(\"macroCardsContainer\").innerHTML = macro.map(m => {\n          const s = Math.max(0, Math.min(100, Number(m.score) || 0));\n          const tone = m.wind === \"顺风\" ? \"sage\" : m.wind === \"逆风\" ? \"terra\" : \"ochre\";\n          const col = tone === \"sage\" ? \"var(--sage)\" : tone === \"terra\" ? \"var(--terra)\" : \"var(--ochre)\";\n          const src = safeUrl(m.source_url);\n          return `\n            <article class=\"macro-card\" data-macro-card=\"${esc(m.chain_id)}\" tabindex=\"-1\">\n              <div class=\"kpi-row\" style=\"flex-wrap:wrap;\">\n                <strong style=\"font-size:15px;\">${fmtHtml(m.title)}</strong>\n                <span class=\"pill tone-${tone}\">${fmtHtml(m.state)} · ${fmtHtml(m.wind)}</span>\n              </div>\n              <div>\n                <div class=\"gauge-labels\"><span>高压逆风</span><strong>温度分 ${s} / 100</strong><span>顺风宽松</span></div>\n                <div class=\"bar-bg\"><div class=\"bar-fill\" style=\"width:${s}%;background:${col};\"></div></div>\n              </div>\n              <div class=\"grid-2\">\n                <div class=\"macro-kpi\">\n                  <div class=\"macro-kpi-top\"><span>${fmtHtml(m.m1_label)}</span><span>${esc(m.m1_date || \"\")}</span></div>\n                  <div class=\"macro-kpi-val\">${esc(m.m1_val || \"--\")}</div>\n                  <div class=\"muted\" style=\"font-size:11px;margin-top:2px;\">${fmtHtml(m.m1_sub || \"\")}</div>\n                </div>\n                <div class=\"macro-kpi\">\n                  <div class=\"macro-kpi-top\"><span>${fmtHtml(m.m2_label)}</span><span>${esc(m.m2_date || \"\")}</span></div>\n                  <div class=\"macro-kpi-val\">${esc(m.m2_val || \"--\")}</div>\n                  <div class=\"muted\" style=\"font-size:11px;margin-top:2px;\">${fmtHtml(m.m2_sub || \"\")}</div>\n                </div>\n              </div>\n              <div style=\"font-size:12.5px;color:#2C322F;\">${fmtHtml(m.plain)}</div>\n              <div style=\"font-size:12px;color:var(--terra);\"><strong>核心隐忧：</strong>${fmtHtml(m.concern)}</div>\n              ${src ? `<div><a class=\"src-link\" style=\"font-size:12px;\" href=\"${esc(src)}\" target=\"_blank\" rel=\"noopener noreferrer\">查看一手真源 ↗</a></div>` : \"\"}\n            </article>\n          `;\n        }).join(\"\");\n\n        const cal = STORE.state?.calendar || [];\n        document.getElementById(\"calendarContainer\").innerHTML = cal.length ? cal.map(ev => {\n          const src = safeUrl(ev.source_url);\n          return `<div class=\"feed-item\">\n            <div class=\"feed-meta\">\n              <div style=\"display:flex;gap:6px;align-items:center;flex-wrap:wrap;\">\n                <span class=\"pill tone-slate\">${esc(ev.day)}</span>\n                <span>${esc(ev.time)}</span>\n                <span class=\"pill ${toneCls(ev.tone)}\">${esc(ev.tag)}</span>\n              </div>\n              ${src ? `<a class=\"src-link\" href=\"${esc(src)}\" target=\"_blank\" rel=\"noopener noreferrer\">日程来源 ↗</a>` : \"\"}\n            </div>\n            <div class=\"feed-title\">${fmtHtml(ev.title)}</div>\n            <div class=\"feed-body\">${fmtHtml(ev.desc)}</div>\n          </div>`;\n        }).join(\"\") : '<div class=\"empty-box\">近期暂无关键日程</div>';\n\n        const hist = STORE.state?.history || [];\n        const toggleBtn = document.getElementById(\"toggleHistory\");\n        toggleBtn.hidden = hist.length <= 5;\n        toggleBtn.textContent = STORE.historyExpanded ? \"收起\" : \"展开全部\";\n        const shown = STORE.historyExpanded ? hist : hist.slice(0, 5);\n        document.getElementById(\"historyLog\").innerHTML = shown.length ? shown.map(h => `\n          <div class=\"feed-item\">\n            <div class=\"feed-meta\"><span class=\"pill ${toneCls(h.tone)}\">${esc(h.type)}</span><span>${esc(h.time)}</span></div>\n            <div class=\"feed-title\">${fmtHtml(h.title)}</div>\n            <div class=\"feed-body\">${fmtHtml(h.detail)}</div>\n            ${h.lesson ? `<div class=\"muted\" style=\"font-size:11.5px;\">复盘经验：${fmtHtml(h.lesson)}</div>` : \"\"}\n          </div>\n        `).join(\"\") : '<div class=\"empty-box\">暂无演进日志</div>';\n      }\n\n      /* Tab 5: Chinese News Feed */\n      function renderNews() {\n        const el = document.getElementById(\"newsContainer\");\n        const items = STORE.news?.items || [];\n        if (STORE.newsBusy && !items.length) { el.innerHTML = '<div class=\"empty-box\">正在同步最新中文快讯...</div>'; return; }\n        if (!items.length) { el.innerHTML = `<div class=\"empty-box\">${esc(STORE.newsErr || \"暂无快讯，请点击右上角「刷新快讯」\")}</div>`; return; }\n        el.innerHTML = items.map(it => {\n          const u = safeUrl(it.link);\n          return `<article class=\"feed-item\">\n            <div class=\"feed-meta\">\n              <span>${esc(it.source || \"财经快讯\")}${it.tag ? \" · \" + esc(it.tag) : \"\"}</span>\n              <span class=\"mono\">${esc(it.pubDate || \"\")}</span>\n            </div>\n            <div class=\"feed-title\">${fmtHtml(it.title)}</div>\n            ${it.summary ? `<div class=\"feed-body\">${fmtHtml(it.summary)}</div>` : \"\"}\n            ${u ? `<div><a class=\"src-link\" style=\"font-size:11.5px;\" href=\"${esc(u)}\" target=\"_blank\" rel=\"noopener noreferrer\">查看原文 ↗</a></div>` : \"\"}\n          </article>`;\n        }).join(\"\");\n      }\n\n      function renderOverviewTrend() {\n        const labels = STORE.state?.analytics?.sparkLabels || [];\n        const series = (STORE.state?.mainlines || []).map((m, i) => ({\n          label: `${m.id} ${m.title}`, values: m.spark || [], color: PALETTE[i % PALETTE.length],\n        }));\n        renderSvgLineChart(\"mlOverviewSvg\", labels, series, \"mainlineTrendLegend\", \"\", 100, \"overview\");\n      }\n\n      function applyState() {\n        renderHero();\n        renderQuoteRibbon();\n        renderMomentum();\n        renderMainlines();\n        renderSetupRadar();\n        renderCandidates();\n        renderLinkage();\n        renderMacro();\n        if (document.getElementById(\"mainlineTrend\")?.open) renderOverviewTrend();\n      }\n\n      /* Networking & Boot Cache */\n      const CACHE_KEY = \"desk-boot-cache-v2\";\n      const inFlight = { state: null, live: null, news: null };\n      const reqVer = { state: 0, live: 0, news: 0 };\n\n      function loadCache() {\n        try {\n          const raw = JSON.parse(localStorage.getItem(CACHE_KEY) || \"null\");\n          if (!raw || Date.now() - raw.savedAt > 86400000) return;\n          if (raw.state?.meta && Array.isArray(raw.state.mainlines)) { STORE.state = raw.state; STORE.stateSource = \"cache\"; }\n          if (Array.isArray(raw.live?.quotes)) { STORE.live = raw.live; STORE.liveSource = \"cache\"; }\n          if (Array.isArray(raw.news?.items)) STORE.news = raw.news;\n        } catch (_) {}\n      }\n      function saveCache() {\n        try {\n          localStorage.setItem(CACHE_KEY, JSON.stringify({ savedAt: Date.now(), state: STORE.state, live: STORE.live, news: STORE.news }));\n        } catch (_) {}\n      }\n\n      async function fetchJson(key, path, force = false, timeoutMs = 8500) {\n        if (!force && inFlight[key]) return { skip: true };\n        if (force && inFlight[key]) try { inFlight[key].abort(); } catch (_) {}\n        const ver = ++reqVer[key];\n        const ctrl = new AbortController();\n        inFlight[key] = ctrl;\n        const timer = setTimeout(() => ctrl.abort(), timeoutMs);\n        try {\n          const sep = path.includes(\"?\") ? \"&\" : \"?\";\n          const resp = await fetch(force ? `${path}${sep}force=1` : path, { cache: force ? \"no-store\" : \"default\", signal: ctrl.signal });\n          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);\n          const data = await resp.json();\n          return ver === reqVer[key] ? { data } : { skip: true };\n        } finally {\n          clearTimeout(timer);\n          if (inFlight[key] === ctrl) inFlight[key] = null;\n        }\n      }\n\n      async function fetchState(force = false) {\n        STORE.stateBusy = true; updateSyncPill();\n        try {\n          const r = await fetchJson(\"state\", \"/api/state\", force);\n          if (r.skip) return;\n          if (!r.data?.meta || !Array.isArray(r.data.mainlines)) throw new Error(\"数据格式异常\");\n          STORE.state = r.data; STORE.stateSource = \"network\"; STORE.stateErr = \"\";\n          saveCache(); applyState();\n        } catch (e) {\n          STORE.stateErr = `研究同步失败 (${e.message || \"超时\"})`;\n          if (!STORE.state) renderHero();\n        } finally { STORE.stateBusy = false; updateSyncPill(); }\n      }\n\n      async function fetchLive(force = false) {\n        STORE.liveBusy = true; updateSyncPill();\n        try {\n          const r = await fetchJson(\"live\", \"/api/live\", force, force ? 10000 : 8500);\n          if (r.skip) return;\n          if (!Array.isArray(r.data?.quotes)) throw new Error(\"行情格式异常\");\n          STORE.live = r.data; STORE.liveSource = \"network\"; STORE.liveErr = \"\";\n          saveCache(); renderQuoteRibbon();\n          if (STORE.state) { patchHeroKpis(); patchMainlinesLive(); }\n        } catch (e) {\n          STORE.liveErr = \"行情同步失败\";\n          renderQuoteRibbon();\n        } finally { STORE.liveBusy = false; updateSyncPill(); }\n      }\n\n      async function fetchNews(force = false) {\n        STORE.newsBusy = true; renderNews();\n        try {\n          const r = await fetchJson(\"news\", \"/api/news?limit=25\", force);\n          if (r.skip) return;\n          if (Array.isArray(r.data?.items)) { STORE.news = r.data; STORE.newsErr = \"\"; saveCache(); }\n        } catch (e) {\n          STORE.newsErr = \"快讯同步失败\";\n        } finally { STORE.newsBusy = false; renderNews(); }\n      }\n\n      async function refreshAll(force = false) {\n        const btn = document.getElementById(\"btnRefreshAll\");\n        if (force) { btn.disabled = true; btn.textContent = \"刷新中...\"; }\n        try {\n          const jobs = [fetchState(force), fetchLive(force)];\n          if (STORE.activeTab === \"news\" || force) jobs.push(fetchNews(force));\n          await Promise.allSettled(jobs);\n        } finally {\n          if (force) { btn.disabled = false; btn.textContent = \"刷新\"; }\n        }\n      }\n\n      /* Interactions */\n      function switchTab(tab) {\n        STORE.activeTab = tab;\n        document.querySelectorAll(\".tab-btn\").forEach(b => {\n          const on = b.dataset.tab === tab;\n          b.classList.toggle(\"active\", on);\n          b.setAttribute(\"aria-pressed\", String(on));\n        });\n        document.querySelectorAll(\".tab-panel\").forEach(p => p.classList.toggle(\"active\", p.id === \"panel-\" + tab));\n        if (tab === \"news\" && !STORE.news && !STORE.newsBusy) fetchNews(false);\n      }\n\n      document.addEventListener(\"click\", ev => {\n        const tabBtn = ev.target.closest(\".tab-btn[data-tab]\");\n        if (tabBtn) { switchTab(tabBtn.dataset.tab); return; }\n\n        const mlBtn = ev.target.closest(\"[data-mainline-filter]\");\n        if (mlBtn) {\n          const id = mlBtn.dataset.mainlineFilter;\n          STORE.mainlineFilter = STORE.mainlineFilter === id ? \"\" : id;\n          STORE.setupCategory = \"all\";\n          renderMomentum(); renderMainlines(); renderSetupRadar();\n          document.getElementById(\"setupHeading\")?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n          return;\n        }\n        const catBtn = ev.target.closest(\"[data-setup-category]\");\n        if (catBtn) { STORE.setupCategory = catBtn.dataset.setupCategory; renderSetupRadar(); return; }\n\n        const setupDot = ev.target.closest(\"[data-setup-focus]\");\n        if (setupDot) {\n          const card = document.querySelector(`[data-setup-idx=\"${setupDot.dataset.setupFocus}\"]`);\n          if (card) { card.focus({ preventScroll: true }); card.scrollIntoView({ behavior: \"smooth\", block: \"center\" }); }\n          return;\n        }\n        const cfBtn = ev.target.closest(\"[data-cfilter]\");\n        if (cfBtn) { STORE.candFilter = cfBtn.dataset.cfilter; renderCandidates(); return; }\n\n        const candDot = ev.target.closest(\"[data-cand-focus]\");\n        if (candDot) {\n          document.querySelectorAll(\".cand-card.active-card\").forEach(n => n.classList.remove(\"active-card\"));\n          const card = document.querySelector(`[data-cand-id=\"${candDot.dataset.candFocus}\"]`);\n          if (card) { card.classList.add(\"active-card\"); card.scrollIntoView({ behavior: \"smooth\", block: \"center\" }); }\n          return;\n        }\n        const macJump = ev.target.closest(\"[data-macro-jump]\");\n        if (macJump) {\n          document.querySelectorAll(\".macro-card.active-card\").forEach(n => n.classList.remove(\"active-card\"));\n          const card = document.querySelector(`[data-macro-card=\"${macJump.dataset.macroJump}\"]`);\n          if (card) { card.classList.add(\"active-card\"); card.focus({ preventScroll: true }); card.scrollIntoView({ behavior: \"smooth\", block: \"center\" }); }\n        }\n      });\n\n      document.getElementById(\"clearMainlinePill\").onclick = () => {\n        if (!STORE.mainlineFilter) return;\n        STORE.mainlineFilter = \"\"; renderMomentum(); renderMainlines(); renderSetupRadar();\n      };\n      document.getElementById(\"mainlineTrend\").ontoggle = () => {\n        if (document.getElementById(\"mainlineTrend\").open) renderOverviewTrend();\n      };\n      document.getElementById(\"toggleHistory\").onclick = () => {\n        STORE.historyExpanded = !STORE.historyExpanded; renderMacro();\n      };\n      document.getElementById(\"btnRefreshAll\").onclick = () => refreshAll(true);\n      document.getElementById(\"btnRefreshNews\").onclick = () => fetchNews(true);\n\n      /* Boot */\n      initColorMode();\n      loadCache();\n      if (STORE.state) applyState(); else if (STORE.live) renderQuoteRibbon();\n      if (STORE.news) renderNews();\n      updateSyncPill();\n      refreshAll(false);\n\n      setInterval(() => {\n        if (document.hidden) return;\n        fetchLive(false);\n      }, 60000);\n      setInterval(() => {\n        if (document.hidden) return;\n        fetchState(false);\n      }, 180000);\n      document.addEventListener(\"visibilitychange\", () => {\n        if (!document.hidden) refreshAll(false);\n      });\n    })();\n  </script>\n</body>\n</html>\n";
export default INDEX_HTML;
